window.TR_PACKS["w3t-b12"]=[{"id":"w3t-01","topic_id":"web3","subtopic_id":"web3.basics","exercise_type":"sentence","direction":"vi-zh","hsk30_level":2,"hsk30_basis":"manual","hsk20_level":null,"title":"Bitcoin là gì?","context":null,"roles":null,"prompt":"Bitcoin là một loại tiền mã hóa.","answer":"比特币是一种加密货币。","pinyin":"Bǐtèbì shì yìzhǒng jiāmì huòbì.","alternative_answers":[],"segments":[{"who":null,"zh":"比特币是一种加密货币。","pinyin":"Bǐtèbì shì yìzhǒng jiāmì huòbì.","vi":"Bitcoin là một loại tiền mã hóa.","alt_zh":[{"zh":"比特币是一种数字货币。","pinyin":"Bǐtèbì shì yìzhǒng shùzì huòbì.","note":"Cách dịch tương đương"},{"zh":"比特币是一种加密币。","pinyin":"Bǐtèbì shì yìzhǒng jiāmì bì.","note":"Cách dịch tương đương"}],"alt_vi":[{"vi":"Bitcoin là một loại tiền điện tử.","note":"Cách dịch tương đương"}],"avoid_zh":[]}],"vocabulary":[{"word":"比特币","pinyin":"bǐtèbì","meaning_vi":"Bitcoin","hsk30_level":null,"specialized":true},{"word":"一种","pinyin":"yìzhǒng","meaning_vi":"một loại","hsk30_level":null,"specialized":true},{"word":"加密货币","pinyin":"jiāmì huòbì","meaning_vi":"tiền mã hóa","hsk30_level":null,"specialized":true}],"grammar_notes":["A 是一种 B: \"A là một loại B\", cách định nghĩa đơn giản nhất. 种 là lượng từ chỉ chủng loại."],"term_notes":[{"term":"加密货币","explain":"Tiền mã hóa: tài sản số dùng mật mã học để bảo mật và ghi trên blockchain. 数字货币 (tiền số) nghĩa rộng hơn, gồm cả tiền số của ngân hàng trung ương."}],"common_mistakes":[{"wrong":"比特币是一个加密货币。","why":"Nói về chủng loại dùng 一种 tự nhiên hơn 一个."}],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"basic","set":"crypto-trading-50"},{"id":"w3t-02","topic_id":"web3","subtopic_id":"web3.bitcoin","exercise_type":"sentence","direction":"zh-vi","hsk30_level":2,"hsk30_basis":"manual","hsk20_level":null,"title":"Giá Bitcoin tăng rồi","context":null,"roles":null,"prompt":"我买了一点儿比特币，现在价格涨了。","answer":"Tôi đã mua một ít Bitcoin, bây giờ giá đã tăng rồi.","pinyin":"Wǒ mǎi le yìdiǎnr bǐtèbì, xiànzài jiàgé zhǎng le.","alternative_answers":[],"segments":[{"who":null,"zh":"我买了一点儿比特币，现在价格涨了。","pinyin":"Wǒ mǎi le yìdiǎnr bǐtèbì, xiànzài jiàgé zhǎng le.","vi":"Tôi đã mua một ít Bitcoin, bây giờ giá đã tăng rồi.","alt_zh":[],"alt_vi":[{"vi":"Tôi mua một chút Bitcoin, giờ giá lên rồi.","note":"Cách dịch tương đương"}],"avoid_zh":[]}],"vocabulary":[{"word":"一点儿","pinyin":"yìdiǎnr","meaning_vi":"một ít, một chút","hsk30_level":1,"specialized":false},{"word":"价格","pinyin":"jiàgé","meaning_vi":"giá","hsk30_level":4,"specialized":false},{"word":"涨","pinyin":"zhǎng","meaning_vi":"tăng (giá)","hsk30_level":5,"specialized":false}],"grammar_notes":["了 sau động từ (买了) chỉ việc đã xảy ra; 了 cuối câu (涨了) chỉ tình hình đã thay đổi."],"term_notes":[{"term":"涨 / 跌","explain":"Trong tin tức thị trường, 涨 = tăng giá, 跌 = giảm giá. Người trong ngành còn nói 拉盘 (kéo giá lên), 砸盘 (đạp giá xuống)."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"basic","set":"crypto-trading-50"},{"id":"w3t-06","topic_id":"web3","subtopic_id":"web3.exchange","exercise_type":"sentence","direction":"zh-vi","hsk30_level":2,"hsk30_basis":"manual","hsk20_level":null,"title":"Bạn dùng sàn nào?","context":null,"roles":null,"prompt":"你在哪个交易所买币？","answer":"Bạn mua coin ở sàn nào?","pinyin":"Nǐ zài nǎge jiāoyìsuǒ mǎibì?","alternative_answers":[],"segments":[{"who":null,"zh":"你在哪个交易所买币？","pinyin":"Nǐ zài nǎge jiāoyìsuǒ mǎibì?","vi":"Bạn mua coin ở sàn nào?","alt_zh":[],"alt_vi":[{"vi":"Bạn mua tiền mã hóa trên sàn giao dịch nào?","note":"Cách dịch tương đương"}],"avoid_zh":[]}],"vocabulary":[{"word":"哪个","pinyin":"nǎge","meaning_vi":"cái nào","hsk30_level":1,"specialized":false},{"word":"交易所","pinyin":"jiāoyìsuǒ","meaning_vi":"sàn giao dịch","hsk30_level":null,"specialized":true},{"word":"买币","pinyin":"mǎibì","meaning_vi":"mua coin","hsk30_level":null,"specialized":true}],"grammar_notes":["在 + nơi chốn + động từ: trạng ngữ nơi chốn đứng TRƯỚC động từ, khác tiếng Việt (\"mua coin ở sàn nào\")."],"term_notes":[{"term":"交易所","explain":"Sàn giao dịch. Sàn tập trung gọi 中心化交易所 (CEX), sàn phi tập trung gọi 去中心化交易所 (DEX)."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"exchange","set":"crypto-trading-50"},{"id":"w3t-11","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"sentence","direction":"vi-zh","hsk30_level":2,"hsk30_basis":"manual","hsk20_level":null,"title":"Mua ETH bằng USDT","context":null,"roles":null,"prompt":"Tôi muốn mua ETH bằng USDT.","answer":"我想用USDT买ETH。","pinyin":"Wǒ xiǎng yòng USDT mǎi ETH.","alternative_answers":[],"segments":[{"who":null,"zh":"我想用USDT买ETH。","pinyin":"Wǒ xiǎng yòng USDT mǎi ETH.","vi":"Tôi muốn mua ETH bằng USDT.","alt_zh":[{"zh":"我想拿USDT买ETH。","pinyin":"Wǒ xiǎng ná USDT mǎi ETH.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"想","pinyin":"xiǎng","meaning_vi":"muốn","hsk30_level":1,"specialized":false},{"word":"用","pinyin":"yòng","meaning_vi":"dùng, bằng","hsk30_level":3,"specialized":false},{"word":"买","pinyin":"mǎi","meaning_vi":"mua","hsk30_level":1,"specialized":false}],"grammar_notes":["用 + công cụ + động từ: \"dùng… để…\"; phương tiện đứng trước động từ, tiếng Việt thường để sau (\"mua ETH bằng USDT\")."],"term_notes":[{"term":"USDT","explain":"Stablecoin (稳定币) neo theo đô la Mỹ, đồng định giá phổ biến nhất trên các sàn."}],"common_mistakes":[{"wrong":"我想买ETH用USDT。","why":"用USDT phải đứng trước động từ 买."}],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"spot","set":"crypto-trading-50"},{"id":"w3t-38","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"sentence","direction":"zh-vi","hsk30_level":2,"hsk30_basis":"manual","hsk20_level":null,"title":"Đừng vay tiền mua coin","context":null,"roles":null,"prompt":"不要借钱买币。","answer":"Đừng vay tiền để mua coin.","pinyin":"Búyào jièqián mǎibì.","alternative_answers":[],"segments":[{"who":null,"zh":"不要借钱买币。","pinyin":"Búyào jièqián mǎibì.","vi":"Đừng vay tiền để mua coin.","alt_zh":[],"alt_vi":[{"vi":"Đừng đi vay tiền mua tiền mã hóa.","note":"Cách dịch tương đương"}],"avoid_zh":[]}],"vocabulary":[{"word":"不要","pinyin":"búyào","meaning_vi":"đừng","hsk30_level":1,"specialized":false},{"word":"借钱","pinyin":"jièqián","meaning_vi":"vay tiền","hsk30_level":null,"specialized":true},{"word":"买币","pinyin":"mǎibì","meaning_vi":"mua coin","hsk30_level":null,"specialized":true}],"grammar_notes":["不要 + động từ: lời khuyên, cấm đoán \"đừng…\".","借钱买币: hai động từ nối tiếp, động từ sau là mục đích."],"term_notes":[{"term":"借钱炒币","explain":"Vay tiền để đầu cơ coin, một trong những nguyên nhân thua lỗ nặng thường được cảnh báo."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"risk","set":"crypto-trading-50"}];
window.TR_PACKS["w3t-b34"]=[{"id":"w3t-03","topic_id":"web3","subtopic_id":"web3.basics","exercise_type":"paragraph","direction":"vi-zh","hsk30_level":4,"hsk30_basis":"manual","hsk20_level":null,"title":"Coin và token khác nhau thế nào?","context":null,"roles":null,"prompt":"Coin và token không hoàn toàn giống nhau. Bitcoin có blockchain riêng nên được gọi là \"coin\". Nhiều token được phát hành trên blockchain khác, ví dụ token trên Ethereum.","answer":"币和代币不完全一样。比特币有自己的区块链，所以叫“币”。很多代币是在别的区块链上发行的，比如以太坊上的代币。","pinyin":"Bì hé dàibì bù wánquán yíyàng. Bǐtèbì yǒu zìjǐ de qūkuàiliàn, suǒyǐ jiào \"bì\". Hěn duō dàibì shì zài biéde qūkuàiliàn shàng fāxíng de, bǐrú yǐtàifāng shàng de dàibì.","alternative_answers":[],"segments":[{"who":null,"zh":"币和代币不完全一样。","pinyin":"Bì hé dàibì bù wánquán yíyàng.","vi":"Coin và token không hoàn toàn giống nhau.","alt_zh":[{"zh":"币和代币并不完全相同。","pinyin":"Bì hé dàibì bìngbù wánquán xiāngtóng.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"比特币有自己的区块链，所以叫“币”。","pinyin":"Bǐtèbì yǒu zìjǐ de qūkuàiliàn, suǒyǐ jiào \"bì\".","vi":"Bitcoin có blockchain riêng nên được gọi là \"coin\".","alt_zh":[{"zh":"比特币有自己独立的区块链，所以被称为“币”。","pinyin":"Bǐtèbì yǒu zìjǐ dúlì de qūkuàiliàn, suǒyǐ bèi chēngwéi \"bì\".","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"很多代币是在别的区块链上发行的，比如以太坊上的代币。","pinyin":"Hěn duō dàibì shì zài biéde qūkuàiliàn shàng fāxíng de, bǐrú yǐtàifāng shàng de dàibì.","vi":"Nhiều token được phát hành trên blockchain khác, ví dụ token trên Ethereum.","alt_zh":[{"zh":"许多代币是在其他区块链上发行的，比如以太坊上的代币。","pinyin":"Xǔduō dàibì shì zài qítā qūkuàiliàn shàng fāxíng de, bǐrú yǐtàifāng shàng de dàibì.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"代币","pinyin":"dàibì","meaning_vi":"token","hsk30_level":null,"specialized":true},{"word":"不完全","pinyin":"bù wánquán","meaning_vi":"không hoàn toàn","hsk30_level":null,"specialized":true},{"word":"区块链","pinyin":"qūkuàiliàn","meaning_vi":"blockchain","hsk30_level":null,"specialized":true},{"word":"发行","pinyin":"fāxíng","meaning_vi":"phát hành","hsk30_level":6,"specialized":false},{"word":"以太坊","pinyin":"yǐtàifāng","meaning_vi":"Ethereum","hsk30_level":null,"specialized":true}],"grammar_notes":["不完全一样: phủ định một phần (\"không hoàn toàn giống\"), khác 完全不一样 (\"hoàn toàn khác\").","是在…上发行的: cấu trúc 是…的 nhấn mạnh nơi phát hành."],"term_notes":[{"term":"币 / 代币","explain":"Coin (币) chạy trên blockchain riêng như BTC, ETH; token (代币) được phát hành trên blockchain có sẵn, ví dụ token ERC-20 trên Ethereum."}],"common_mistakes":[{"wrong":"币和代币完全不一样。","why":"Câu gốc là \"không hoàn toàn giống\" (不完全一样), không phải \"hoàn toàn khác\"."}],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"basic","set":"crypto-trading-50"},{"id":"w3t-07","topic_id":"web3","subtopic_id":"web3.exchange","exercise_type":"dialogue","direction":"vi-zh","hsk30_level":3,"hsk30_basis":"manual","hsk20_level":null,"title":"Nạp tiền chưa về tài khoản","context":"Người dùng nhắn tin cho bộ phận chăm sóc khách hàng của sàn.","roles":{"客服":"nhân viên hỗ trợ","用户":"người dùng"},"prompt":"Xin chào, tôi có thể giúp gì cho bạn?\nTôi đã nạp 100 USDT nhưng vẫn chưa thấy về tài khoản.\nVui lòng gửi cho tôi mã hash giao dịch, tôi sẽ kiểm tra giúp bạn.","answer":"您好，请问有什么可以帮您？\n我充值了一百USDT，可是还没到账。\n请把交易哈希发给我，我帮您查一下。","pinyin":"Nínhǎo, qǐngwèn yǒu shénme kěyǐ bāng nín? Wǒ chōngzhí le yì bǎi USDT, kěshì hái méi dàozhàng. Qǐng bǎ jiāoyì hāxī fāgěi wǒ, wǒ bāng nín chá yíxià.","alternative_answers":[],"segments":[{"who":"客服","zh":"您好，请问有什么可以帮您？","pinyin":"Nínhǎo, qǐngwèn yǒu shénme kěyǐ bāng nín?","vi":"Xin chào, tôi có thể giúp gì cho bạn?","alt_zh":[{"zh":"您好，有什么可以帮您的吗？","pinyin":"Nínhǎo, yǒu shénme kěyǐ bāng nín de ma?","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":"用户","zh":"我充值了一百USDT，可是还没到账。","pinyin":"Wǒ chōngzhí le yì bǎi USDT, kěshì hái méi dàozhàng.","vi":"Tôi đã nạp 100 USDT nhưng vẫn chưa thấy về tài khoản.","alt_zh":[{"zh":"我充了一百USDT，但是还没到账。","pinyin":"Wǒ chōng le yì bǎi USDT, dànshì hái méi dàozhàng.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":"客服","zh":"请把交易哈希发给我，我帮您查一下。","pinyin":"Qǐng bǎ jiāoyì hāxī fāgěi wǒ, wǒ bāng nín chá yíxià.","vi":"Vui lòng gửi cho tôi mã hash giao dịch, tôi sẽ kiểm tra giúp bạn.","alt_zh":[{"zh":"请发一下交易哈希，我帮您查查。","pinyin":"Qǐng fā yíxià jiāoyì hāxī, wǒ bāng nín chá chá.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"客服","pinyin":"kèfú","meaning_vi":"nhân viên chăm sóc khách hàng","hsk30_level":5,"specialized":false},{"word":"充值","pinyin":"chōngzhí","meaning_vi":"nạp tiền","hsk30_level":5,"specialized":false},{"word":"到账","pinyin":"dàozhàng","meaning_vi":"tiền về tài khoản","hsk30_level":null,"specialized":true},{"word":"交易哈希","pinyin":"jiāoyì hāxī","meaning_vi":"mã hash giao dịch (TxID)","hsk30_level":null,"specialized":true},{"word":"查","pinyin":"chá","meaning_vi":"kiểm tra, tra","hsk30_level":3,"specialized":false}],"grammar_notes":["请问: mở đầu câu hỏi lịch sự.","动词 + 一下 (查一下): làm thử, làm nhanh một chút, giọng nhẹ nhàng."],"term_notes":[{"term":"充值 / 提币","explain":"Trên sàn: 充值 hoặc 充币 = nạp tiền/coin vào sàn; 提币 hoặc 提现 = rút ra."},{"term":"交易哈希","explain":"TxID / Tx Hash: mã định danh duy nhất của giao dịch trên blockchain, dùng để tra cứu trên trình khám phá khối."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"exchange","set":"crypto-trading-50"},{"id":"w3t-08","topic_id":"web3","subtopic_id":"web3.exchange","exercise_type":"paragraph","direction":"zh-vi","hsk30_level":4,"hsk30_basis":"manual","hsk20_level":null,"title":"Phí Maker và Taker","context":null,"roles":null,"prompt":"交易所一般会收取交易手续费。挂单成交的用户叫Maker，手续费通常更低；直接吃单的用户叫Taker，手续费相对高一些。","answer":"Sàn giao dịch thường thu phí giao dịch. Người dùng đặt lệnh chờ và được khớp gọi là Maker, phí thường thấp hơn; người dùng khớp ngay với lệnh có sẵn gọi là Taker, phí cao hơn một chút.","pinyin":"Jiāoyìsuǒ yìbān huì shōuqǔ jiāoyì shǒuxùfèi. Guàdān chéngjiāo de yònghù jiào Maker, shǒuxùfèi tōngcháng gèng dī; Zhíjiē chīdān de yònghù jiào Taker, shǒuxùfèi xiāngduì gāo yìxiē.","alternative_answers":[],"segments":[{"who":null,"zh":"交易所一般会收取交易手续费。","pinyin":"Jiāoyìsuǒ yìbān huì shōuqǔ jiāoyì shǒuxùfèi.","vi":"Sàn giao dịch thường thu phí giao dịch.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"挂单成交的用户叫Maker，手续费通常更低；","pinyin":"Guàdān chéngjiāo de yònghù jiào Maker, shǒuxùfèi tōngcháng gèng dī;","vi":"Người dùng đặt lệnh chờ và được khớp gọi là Maker, phí thường thấp hơn;","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"直接吃单的用户叫Taker，手续费相对高一些。","pinyin":"Zhíjiē chīdān de yònghù jiào Taker, shǒuxùfèi xiāngduì gāo yìxiē.","vi":"người dùng khớp ngay với lệnh có sẵn gọi là Taker, phí cao hơn một chút.","alt_zh":[],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"收取","pinyin":"shōuqǔ","meaning_vi":"thu (phí)","hsk30_level":6,"specialized":false},{"word":"手续费","pinyin":"shǒuxùfèi","meaning_vi":"phí giao dịch","hsk30_level":null,"specialized":true},{"word":"挂单","pinyin":"guàdān","meaning_vi":"đặt lệnh chờ","hsk30_level":null,"specialized":true},{"word":"成交","pinyin":"chéngjiāo","meaning_vi":"khớp lệnh","hsk30_level":6,"specialized":false},{"word":"吃单","pinyin":"chīdān","meaning_vi":"khớp với lệnh có sẵn","hsk30_level":null,"specialized":true},{"word":"相对","pinyin":"xiāngduì","meaning_vi":"tương đối","hsk30_level":5,"specialized":false}],"grammar_notes":["叫: \"gọi là\", dùng để định nghĩa (…的用户叫Maker).","相对 + tính từ + 一些: \"tương đối… hơn một chút\", so sánh nhẹ."],"term_notes":[{"term":"Maker / Taker","explain":"Maker (挂单方) đưa thêm thanh khoản vào sổ lệnh nên thường được phí thấp; Taker (吃单方) lấy thanh khoản có sẵn nên phí cao hơn."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"exchange","set":"crypto-trading-50"},{"id":"w3t-09","topic_id":"web3","subtopic_id":"web3.exchange","exercise_type":"paragraph","direction":"vi-zh","hsk30_level":4,"hsk30_basis":"manual","hsk20_level":null,"title":"Xác minh danh tính (KYC)","context":null,"roles":null,"prompt":"Để tuân thủ yêu cầu quản lý, phần lớn các sàn đều yêu cầu người dùng hoàn thành xác minh danh tính. Sau khi hoàn tất KYC, hạn mức rút coin của người dùng sẽ tăng và có thể dùng thêm nhiều tính năng.","answer":"为了遵守监管要求，大部分交易所都要求用户完成身份认证。完成KYC以后，用户的提币额度会提高，也可以使用更多功能。","pinyin":"Wèile zūnshǒu jiānguǎn yāoqiú, dà bùfen jiāoyìsuǒ dōu yāoqiú yònghù wánchéng shēnfèn rènzhèng. Wánchéng KYC yǐhòu, yònghù de tíbì édù huì tígāo, yě kěyǐ shǐyòng gèng duō gōngnéng.","alternative_answers":[],"segments":[{"who":null,"zh":"为了遵守监管要求，大部分交易所都要求用户完成身份认证。","pinyin":"Wèile zūnshǒu jiānguǎn yāoqiú, dà bùfen jiāoyìsuǒ dōu yāoqiú yònghù wánchéng shēnfèn rènzhèng.","vi":"Để tuân thủ yêu cầu quản lý, phần lớn các sàn đều yêu cầu người dùng hoàn thành xác minh danh tính.","alt_zh":[{"zh":"为了符合监管要求，大多数交易所都要求用户进行身份认证。","pinyin":"Wèile fúhé jiānguǎn yāoqiú, dà duōshù jiāoyìsuǒ dōu yāoqiú yònghù jìnxíng shēnfèn rènzhèng.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"完成KYC以后，用户的提币额度会提高，也可以使用更多功能。","pinyin":"Wánchéng KYC yǐhòu, yònghù de tíbì édù huì tígāo, yě kěyǐ shǐyòng gèng duō gōngnéng.","vi":"Sau khi hoàn tất KYC, hạn mức rút coin của người dùng sẽ tăng và có thể dùng thêm nhiều tính năng.","alt_zh":[{"zh":"完成KYC之后，提币额度会提高，还能使用更多功能。","pinyin":"Wánchéng KYC zhīhòu, tíbì édù huì tígāo, hái néng shǐyòng gèng duō gōngnéng.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"遵守","pinyin":"zūnshǒu","meaning_vi":"tuân thủ","hsk30_level":5,"specialized":false},{"word":"监管","pinyin":"jiānguǎn","meaning_vi":"quản lý, giám sát (của nhà nước)","hsk30_level":"7-9","specialized":false},{"word":"身份认证","pinyin":"shēnfèn rènzhèng","meaning_vi":"xác minh danh tính","hsk30_level":null,"specialized":true},{"word":"提币","pinyin":"tíbì","meaning_vi":"rút coin","hsk30_level":null,"specialized":true},{"word":"额度","pinyin":"édù","meaning_vi":"hạn mức","hsk30_level":"7-9","specialized":false},{"word":"功能","pinyin":"gōngnéng","meaning_vi":"tính năng","hsk30_level":5,"specialized":false}],"grammar_notes":["为了…，…: \"để…\", mệnh đề mục đích đứng đầu câu.","完成…以后: \"sau khi hoàn thành…\", 以后 đặt SAU mệnh đề, ngược với tiếng Việt."],"term_notes":[{"term":"KYC","explain":"Know Your Customer – xác minh danh tính khách hàng (实名认证 / 身份认证), thường gồm giấy tờ tùy thân và ảnh khuôn mặt."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"exchange","set":"crypto-trading-50"},{"id":"w3t-12","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"sentence","direction":"zh-vi","hsk30_level":3,"hsk30_basis":"manual","hsk20_level":null,"title":"Giao dịch spot là gì?","context":null,"roles":null,"prompt":"现货交易就是用一种资产直接买另一种资产。","answer":"Giao dịch giao ngay (spot) là dùng một tài sản để mua trực tiếp một tài sản khác.","pinyin":"Xiànhuò jiāoyì jiùshì yòng yìzhǒng zīchǎn zhíjiē mǎi lìng yìzhǒng zīchǎn.","alternative_answers":[],"segments":[{"who":null,"zh":"现货交易就是用一种资产直接买另一种资产。","pinyin":"Xiànhuò jiāoyì jiùshì yòng yìzhǒng zīchǎn zhíjiē mǎi lìng yìzhǒng zīchǎn.","vi":"Giao dịch giao ngay (spot) là dùng một tài sản để mua trực tiếp một tài sản khác.","alt_zh":[],"alt_vi":[{"vi":"Giao dịch spot nghĩa là dùng tài sản này mua thẳng tài sản khác.","note":"Cách dịch tương đương"}],"avoid_zh":[]}],"vocabulary":[{"word":"现货","pinyin":"xiànhuò","meaning_vi":"giao ngay (spot)","hsk30_level":6,"specialized":false},{"word":"就是","pinyin":"jiùshì","meaning_vi":"chính là","hsk30_level":4,"specialized":false},{"word":"资产","pinyin":"zīchǎn","meaning_vi":"tài sản","hsk30_level":6,"specialized":false},{"word":"直接","pinyin":"zhíjiē","meaning_vi":"trực tiếp","hsk30_level":4,"specialized":false},{"word":"另一种","pinyin":"lìng yìzhǒng","meaning_vi":"một loại khác","hsk30_level":null,"specialized":true}],"grammar_notes":["A 就是 B: \"A chính là B\", nhấn mạnh định nghĩa."],"term_notes":[{"term":"现货交易","explain":"Spot: mua bán và nhận tài sản ngay, không dùng đòn bẩy, khác giao dịch hợp đồng (合约交易)."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"spot","set":"crypto-trading-50"},{"id":"w3t-13","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"vi-zh","hsk30_level":4,"hsk30_basis":"manual","hsk20_level":null,"title":"Cặp giao dịch BTC/USDT","context":null,"roles":null,"prompt":"Trong cặp giao dịch BTC/USDT, BTC là đồng tiền cơ sở, USDT là đồng tiền định giá. Giá hiển thị là một BTC đáng giá bao nhiêu USDT.","answer":"在BTC/USDT这个交易对里，BTC是基础货币，USDT是计价货币。价格显示的是一个BTC值多少USDT。","pinyin":"Zài BTC/USDT zhège jiāoyìduì lǐ, BTC shì jīchǔ huòbì, USDT shì jìjià huòbì. Jiàgé xiǎnshì de shì yí gè BTC zhí duōshǎo USDT.","alternative_answers":[],"segments":[{"who":null,"zh":"在BTC/USDT这个交易对里，BTC是基础货币，USDT是计价货币。","pinyin":"Zài BTC/USDT zhège jiāoyìduì lǐ, BTC shì jīchǔ huòbì, USDT shì jìjià huòbì.","vi":"Trong cặp giao dịch BTC/USDT, BTC là đồng tiền cơ sở, USDT là đồng tiền định giá.","alt_zh":[{"zh":"在BTC/USDT交易对中，BTC是基础货币，USDT是计价货币。","pinyin":"Zài BTC/USDT jiāoyìduì zhōng, BTC shì jīchǔ huòbì, USDT shì jìjià huòbì.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"价格显示的是一个BTC值多少USDT。","pinyin":"Jiàgé xiǎnshì de shì yí gè BTC zhí duōshǎo USDT.","vi":"Giá hiển thị là một BTC đáng giá bao nhiêu USDT.","alt_zh":[{"zh":"显示的价格就是一个BTC等于多少USDT。","pinyin":"Xiǎnshì de jiàgé jiùshì yí gè BTC děngyú duōshǎo USDT.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"交易对","pinyin":"jiāoyìduì","meaning_vi":"cặp giao dịch","hsk30_level":null,"specialized":true},{"word":"基础货币","pinyin":"jīchǔ huòbì","meaning_vi":"đồng tiền cơ sở","hsk30_level":null,"specialized":true},{"word":"计价货币","pinyin":"jìjià huòbì","meaning_vi":"đồng tiền định giá","hsk30_level":null,"specialized":true},{"word":"显示","pinyin":"xiǎnshì","meaning_vi":"hiển thị","hsk30_level":5,"specialized":false},{"word":"值","pinyin":"zhí","meaning_vi":"đáng giá","hsk30_level":4,"specialized":false}],"grammar_notes":["…的是…: \"cái… là…\", nhấn mạnh vị ngữ (价格显示的是…).","值 + số lượng: \"đáng giá bao nhiêu\"."],"term_notes":[{"term":"交易对","explain":"Cặp giao dịch: đồng đứng trước là tài sản được mua bán, đồng đứng sau dùng để định giá và thanh toán."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"spot","set":"crypto-trading-50"},{"id":"w3t-14","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"zh-vi","hsk30_level":4,"hsk30_basis":"manual","hsk20_level":null,"title":"Lệnh thị trường và trượt giá","context":null,"roles":null,"prompt":"如果你想马上成交，可以下市价单。市价单会按照当前最好的价格成交，但在市场波动大的时候，可能会出现滑点。","answer":"Nếu bạn muốn khớp lệnh ngay, có thể đặt lệnh thị trường. Lệnh thị trường sẽ khớp theo giá tốt nhất hiện tại, nhưng khi thị trường biến động mạnh có thể xảy ra trượt giá.","pinyin":"Rúguǒ nǐ xiǎng mǎshàng chéngjiāo, kěyǐ xià shìjiàdān. Shìjiàdān huì ànzhào dāngqián zuìhǎo de jiàgé chéngjiāo, dàn zài shìchǎng bōdòng dà de shíhou, kěnéng huì chūxiàn huádiǎn.","alternative_answers":[],"segments":[{"who":null,"zh":"如果你想马上成交，可以下市价单。","pinyin":"Rúguǒ nǐ xiǎng mǎshàng chéngjiāo, kěyǐ xià shìjiàdān.","vi":"Nếu bạn muốn khớp lệnh ngay, có thể đặt lệnh thị trường.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"市价单会按照当前最好的价格成交，但在市场波动大的时候，可能会出现滑点。","pinyin":"Shìjiàdān huì ànzhào dāngqián zuìhǎo de jiàgé chéngjiāo, dàn zài shìchǎng bōdòng dà de shíhou, kěnéng huì chūxiàn huádiǎn.","vi":"Lệnh thị trường sẽ khớp theo giá tốt nhất hiện tại, nhưng khi thị trường biến động mạnh có thể xảy ra trượt giá.","alt_zh":[],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"马上","pinyin":"mǎshàng","meaning_vi":"ngay lập tức","hsk30_level":3,"specialized":false},{"word":"下单","pinyin":"xiàdān","meaning_vi":"đặt lệnh","hsk30_level":6,"specialized":false},{"word":"市价单","pinyin":"shìjiàdān","meaning_vi":"lệnh thị trường","hsk30_level":null,"specialized":true},{"word":"按照","pinyin":"ànzhào","meaning_vi":"theo","hsk30_level":4,"specialized":false},{"word":"当前","pinyin":"dāngqián","meaning_vi":"hiện tại","hsk30_level":5,"specialized":false},{"word":"波动","pinyin":"bōdòng","meaning_vi":"biến động","hsk30_level":"7-9","specialized":false},{"word":"滑点","pinyin":"huádiǎn","meaning_vi":"trượt giá","hsk30_level":null,"specialized":true}],"grammar_notes":["下 + loại lệnh (下市价单): 下 là động từ \"đặt (lệnh)\".","…的时候: \"khi…\", đặt sau mệnh đề."],"term_notes":[{"term":"市价单","explain":"Market order: khớp ngay theo giá tốt nhất đang có."},{"term":"滑点","explain":"Slippage: chênh lệch giữa giá dự kiến và giá khớp thực tế, thường xảy ra khi thanh khoản mỏng hoặc thị trường biến động mạnh."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"spot","set":"crypto-trading-50"},{"id":"w3t-16","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"sentence","direction":"zh-vi","hsk30_level":3,"hsk30_basis":"manual","hsk20_level":null,"title":"Long và Short","context":null,"roles":null,"prompt":"看涨的时候可以做多，看跌的时候可以做空。","answer":"Khi dự đoán giá tăng có thể mở lệnh Long, khi dự đoán giá giảm có thể mở lệnh Short.","pinyin":"Kànzhǎng de shíhou kěyǐ zuòduō, kàndiē de shíhou kěyǐ zuòkōng.","alternative_answers":[],"segments":[{"who":null,"zh":"看涨的时候可以做多，看跌的时候可以做空。","pinyin":"Kànzhǎng de shíhou kěyǐ zuòduō, kàndiē de shíhou kěyǐ zuòkōng.","vi":"Khi dự đoán giá tăng có thể mở lệnh Long, khi dự đoán giá giảm có thể mở lệnh Short.","alt_zh":[],"alt_vi":[{"vi":"Khi kỳ vọng giá lên thì có thể mua Long, khi kỳ vọng giá xuống thì có thể bán Short.","note":"Cách dịch tương đương"}],"avoid_zh":[]}],"vocabulary":[{"word":"看涨","pinyin":"kànzhǎng","meaning_vi":"dự đoán giá tăng","hsk30_level":null,"specialized":true},{"word":"看跌","pinyin":"kàndiē","meaning_vi":"dự đoán giá giảm","hsk30_level":null,"specialized":true},{"word":"做多","pinyin":"zuòduō","meaning_vi":"mở vị thế Long","hsk30_level":null,"specialized":true},{"word":"做空","pinyin":"zuòkōng","meaning_vi":"mở vị thế Short","hsk30_level":null,"specialized":true}],"grammar_notes":["…的时候, …的时候: hai vế song song đối nhau, dịch \"khi…, khi…\"."],"term_notes":[{"term":"做多 / 做空","explain":"做多 (Long) có lãi khi giá tăng; 做空 (Short) có lãi khi giá giảm. Người Việt trong ngành thường giữ nguyên \"Long/Short\"."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"futures","set":"crypto-trading-50"},{"id":"w3t-17","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"vi-zh","hsk30_level":4,"hsk30_basis":"manual","hsk20_level":null,"title":"Hợp đồng vĩnh cửu","context":null,"roles":null,"prompt":"Hợp đồng vĩnh cửu không có ngày đáo hạn, người dùng có thể giữ vị thế mãi. Để giá hợp đồng sát với giá giao ngay, các bên Long và Short sẽ định kỳ trả phí funding cho nhau.","answer":"永续合约没有到期日，用户可以一直持仓。为了让合约价格接近现货价格，多头和空头之间会定期支付资金费用。","pinyin":"Yǒngxù héyuē méiyǒu dàoqīrì, yònghù kěyǐ yìzhí chícāng. Wèile ràng héyuē jiàgé jiējìn xiànhuò jiàgé, duōtóu hé kōngtóu zhījiān huì dìngqī zhīfù zījīn fèiyòng.","alternative_answers":[],"segments":[{"who":null,"zh":"永续合约没有到期日，用户可以一直持仓。","pinyin":"Yǒngxù héyuē méiyǒu dàoqīrì, yònghù kěyǐ yìzhí chícāng.","vi":"Hợp đồng vĩnh cửu không có ngày đáo hạn, người dùng có thể giữ vị thế mãi.","alt_zh":[{"zh":"永续合约没有交割日，用户可以一直持有仓位。","pinyin":"Yǒngxù héyuē méiyǒu jiāogē rì, yònghù kěyǐ yìzhí chíyǒu cāngwèi.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"为了让合约价格接近现货价格，多头和空头之间会定期支付资金费用。","pinyin":"Wèile ràng héyuē jiàgé jiējìn xiànhuò jiàgé, duōtóu hé kōngtóu zhījiān huì dìngqī zhīfù zījīn fèiyòng.","vi":"Để giá hợp đồng sát với giá giao ngay, các bên Long và Short sẽ định kỳ trả phí funding cho nhau.","alt_zh":[{"zh":"为了让合约价格贴近现货价格，多空双方会定期互相支付资金费用。","pinyin":"Wèile ràng héyuē jiàgé tiējìn xiànhuò jiàgé, duō kōng shuāngfāng huì dìngqī hùxiāng zhīfù zījīn fèiyòng.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"永续合约","pinyin":"yǒngxù héyuē","meaning_vi":"hợp đồng vĩnh cửu","hsk30_level":null,"specialized":true},{"word":"到期日","pinyin":"dàoqīrì","meaning_vi":"ngày đáo hạn","hsk30_level":null,"specialized":true},{"word":"持仓","pinyin":"chícāng","meaning_vi":"giữ vị thế","hsk30_level":null,"specialized":true},{"word":"接近","pinyin":"jiējìn","meaning_vi":"gần, sát","hsk30_level":5,"specialized":false},{"word":"多头","pinyin":"duōtóu","meaning_vi":"phe Long","hsk30_level":null,"specialized":true},{"word":"空头","pinyin":"kōngtóu","meaning_vi":"phe Short","hsk30_level":null,"specialized":true},{"word":"定期","pinyin":"dìngqī","meaning_vi":"định kỳ","hsk30_level":5,"specialized":false}],"grammar_notes":["让 + đối tượng + động từ/tính từ: \"làm cho…\", câu kiêm ngữ.","之间: \"giữa…\", đặt sau danh từ."],"term_notes":[{"term":"永续合约","explain":"Perpetual: hợp đồng tương lai không có ngày giao nhận, phổ biến nhất trên sàn crypto."},{"term":"资金费用","explain":"Phí funding: khoản Long và Short trả cho nhau theo chu kỳ (thường 8 giờ), không phải phí của sàn."}],"common_mistakes":[{"wrong":"交易所会定期收取资金费用。","why":"Funding được trả giữa hai phe Long và Short, sàn không thu khoản này."}],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"futures","set":"crypto-trading-50"},{"id":"w3t-23","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"sentence","direction":"vi-zh","hsk30_level":3,"hsk30_basis":"manual","hsk20_level":null,"title":"Đòn bẩy và rủi ro","context":null,"roles":null,"prompt":"Đòn bẩy càng cao thì rủi ro càng lớn.","answer":"杠杆越高，风险越大。","pinyin":"Gànggǎn yuè gāo, fēngxiǎn yuè dà.","alternative_answers":[],"segments":[{"who":null,"zh":"杠杆越高，风险越大。","pinyin":"Gànggǎn yuè gāo, fēngxiǎn yuè dà.","vi":"Đòn bẩy càng cao thì rủi ro càng lớn.","alt_zh":[{"zh":"杠杆越大，风险就越大。","pinyin":"Gànggǎn yuè dà, fēngxiǎn jiù yuè dà.","note":"Cách dịch tương đương"},{"zh":"杠杆越高，风险就越大。","pinyin":"Gànggǎn yuè gāo, fēngxiǎn jiù yuè dà.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"杠杆","pinyin":"gànggǎn","meaning_vi":"đòn bẩy","hsk30_level":"7-9","specialized":false},{"word":"越…越…","pinyin":"yuè… yuè…","meaning_vi":"càng… càng…","hsk30_level":null,"specialized":true},{"word":"风险","pinyin":"fēngxiǎn","meaning_vi":"rủi ro","hsk30_level":5,"specialized":false}],"grammar_notes":["越 A，越 B: \"càng A thì càng B\"; có thể thêm 就 ở vế sau."],"term_notes":[{"term":"杠杆","explain":"Leverage: vay thêm vốn để mở vị thế lớn hơn số ký quỹ, ví dụ 10倍杠杆 = đòn bẩy 10 lần. Lãi và lỗ đều được phóng đại."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"margin","set":"crypto-trading-50"},{"id":"w3t-24","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"zh-vi","hsk30_level":4,"hsk30_basis":"manual","hsk20_level":null,"title":"Lệnh giới hạn","context":null,"roles":null,"prompt":"限价单可以让你自己设定买入或卖出的价格。只有市场价格达到你设定的价格时，订单才会成交。","answer":"Lệnh giới hạn cho phép bạn tự đặt giá mua hoặc bán. Chỉ khi giá thị trường chạm mức giá bạn đặt thì lệnh mới được khớp.","pinyin":"Xiànjiàdān kěyǐ ràng nǐ zìjǐ shèdìng mǎirù huò màichū de jiàgé. Zhǐyǒu shìchǎng jiàgé dádào nǐ shèdìng de jiàgé shí, dìngdān cái huì chéngjiāo.","alternative_answers":[],"segments":[{"who":null,"zh":"限价单可以让你自己设定买入或卖出的价格。","pinyin":"Xiànjiàdān kěyǐ ràng nǐ zìjǐ shèdìng mǎirù huò màichū de jiàgé.","vi":"Lệnh giới hạn cho phép bạn tự đặt giá mua hoặc bán.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"只有市场价格达到你设定的价格时，订单才会成交。","pinyin":"Zhǐyǒu shìchǎng jiàgé dádào nǐ shèdìng de jiàgé shí, dìngdān cái huì chéngjiāo.","vi":"Chỉ khi giá thị trường chạm mức giá bạn đặt thì lệnh mới được khớp.","alt_zh":[],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"限价单","pinyin":"xiànjiàdān","meaning_vi":"lệnh giới hạn","hsk30_level":null,"specialized":true},{"word":"设定","pinyin":"shèdìng","meaning_vi":"thiết lập, đặt","hsk30_level":"7-9","specialized":false},{"word":"买入","pinyin":"mǎirù","meaning_vi":"mua vào","hsk30_level":null,"specialized":true},{"word":"卖出","pinyin":"màichū","meaning_vi":"bán ra","hsk30_level":null,"specialized":true},{"word":"达到","pinyin":"dádào","meaning_vi":"đạt tới","hsk30_level":4,"specialized":false},{"word":"订单","pinyin":"dìngdān","meaning_vi":"lệnh, đơn","hsk30_level":6,"specialized":false}],"grammar_notes":["只有…才…: \"chỉ khi… mới…\", điều kiện cần."],"term_notes":[{"term":"限价单","explain":"Limit order: chỉ khớp ở mức giá đặt hoặc tốt hơn; không bị trượt giá nhưng có thể không được khớp."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"margin","set":"crypto-trading-50"},{"id":"w3t-28","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"sentence","direction":"zh-vi","hsk30_level":3,"hsk30_basis":"manual","hsk20_level":null,"title":"Cây nến tăng lớn","context":null,"roles":null,"prompt":"今天比特币的K线是一根大阳线。","answer":"Hôm nay nến của Bitcoin là một cây nến tăng lớn.","pinyin":"Jīntiān bǐtèbì de K xiàn shì yì gēn dà yángxiàn.","alternative_answers":[],"segments":[{"who":null,"zh":"今天比特币的K线是一根大阳线。","pinyin":"Jīntiān bǐtèbì de K xiàn shì yì gēn dà yángxiàn.","vi":"Hôm nay nến của Bitcoin là một cây nến tăng lớn.","alt_zh":[],"alt_vi":[{"vi":"Hôm nay Bitcoin có một cây nến xanh dài.","note":"Cách dịch tương đương"}],"avoid_zh":[]}],"vocabulary":[{"word":"K线","pinyin":"K xiàn","meaning_vi":"nến (biểu đồ nến)","hsk30_level":null,"specialized":true},{"word":"根","pinyin":"gēn","meaning_vi":"lượng từ cho vật dài","hsk30_level":5,"specialized":false},{"word":"阳线","pinyin":"yángxiàn","meaning_vi":"nến tăng","hsk30_level":null,"specialized":true}],"grammar_notes":["一根 + danh từ: 根 là lượng từ cho vật dài, mảnh như cây nến, cây cột."],"term_notes":[{"term":"阳线 / 阴线","explain":"阳线 = nến tăng (giá đóng cửa cao hơn giá mở cửa), 阴线 = nến giảm. Lưu ý: ở Trung Quốc nến tăng thường màu đỏ, nến giảm màu xanh, ngược với nhiều sàn quốc tế."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"ta","set":"crypto-trading-50"},{"id":"w3t-29","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"vi-zh","hsk30_level":4,"hsk30_basis":"manual","hsk20_level":null,"title":"Hỗ trợ và kháng cự","context":null,"roles":null,"prompt":"Giá nhiều lần ngừng giảm tại cùng một vị trí, vị trí đó gọi là vùng hỗ trợ. Ngược lại, vị trí mà giá nhiều lần không tăng lên được gọi là vùng kháng cự.","answer":"价格多次在同一个位置停止下跌，这个位置就叫支撑位。相反，价格多次涨不上去的位置叫阻力位。","pinyin":"Jiàgé duōcì zài tóngyī gè wèizhì tíngzhǐ xiàdiē, zhège wèizhì jiù jiào zhīchēngwèi. Xiāngfǎn, jiàgé duōcì zhǎngbushàngqù de wèizhì jiào zǔlìwèi.","alternative_answers":[],"segments":[{"who":null,"zh":"价格多次在同一个位置停止下跌，这个位置就叫支撑位。","pinyin":"Jiàgé duōcì zài tóngyī gè wèizhì tíngzhǐ xiàdiē, zhège wèizhì jiù jiào zhīchēngwèi.","vi":"Giá nhiều lần ngừng giảm tại cùng một vị trí, vị trí đó gọi là vùng hỗ trợ.","alt_zh":[{"zh":"价格好几次在同一个地方止跌，这个位置就叫支撑位。","pinyin":"Jiàgé hǎo jǐcì zài tóngyī gè dìfāng zhǐ diē, zhège wèizhì jiù jiào zhīchēngwèi.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"相反，价格多次涨不上去的位置叫阻力位。","pinyin":"Xiāngfǎn, jiàgé duōcì zhǎngbushàngqù de wèizhì jiào zǔlìwèi.","vi":"Ngược lại, vị trí mà giá nhiều lần không tăng lên được gọi là vùng kháng cự.","alt_zh":[{"zh":"反过来，价格多次涨不上去的地方叫阻力位。","pinyin":"Fǎnguòlái, jiàgé duōcì zhǎngbushàngqù de dìfāng jiào zǔlìwèi.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"多次","pinyin":"duōcì","meaning_vi":"nhiều lần","hsk30_level":null,"specialized":true},{"word":"位置","pinyin":"wèizhì","meaning_vi":"vị trí","hsk30_level":5,"specialized":false},{"word":"停止","pinyin":"tíngzhǐ","meaning_vi":"ngừng","hsk30_level":4,"specialized":false},{"word":"支撑位","pinyin":"zhīchēngwèi","meaning_vi":"vùng hỗ trợ","hsk30_level":null,"specialized":true},{"word":"相反","pinyin":"xiāngfǎn","meaning_vi":"ngược lại","hsk30_level":4,"specialized":false},{"word":"阻力位","pinyin":"zǔlìwèi","meaning_vi":"vùng kháng cự","hsk30_level":null,"specialized":true}],"grammar_notes":["涨不上去: bổ ngữ khả năng phủ định \"không tăng lên được\".","…的位置叫…: định ngữ dài đứng trước danh từ."],"term_notes":[{"term":"支撑位 / 阻力位","explain":"Support và resistance: vùng giá mà lực mua hoặc lực bán thường đủ mạnh để chặn đà giảm hoặc đà tăng."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"ta","set":"crypto-trading-50"},{"id":"w3t-34","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"zh-vi","hsk30_level":4,"hsk30_basis":"manual","hsk20_level":null,"title":"Giao dịch thuận xu hướng","context":null,"roles":null,"prompt":"顺势交易的意思是跟着趋势走：上涨趋势里找机会做多，下跌趋势里找机会做空，尽量不要逆势抄底。","answer":"Giao dịch thuận xu hướng nghĩa là đi theo xu hướng: trong xu hướng tăng thì tìm cơ hội Long, trong xu hướng giảm thì tìm cơ hội Short, cố gắng không bắt đáy ngược xu hướng.","pinyin":"Shùnshì jiāoyì de yìsi shì gēnzhe qūshì zǒu: Shàngzhǎng qūshì lǐ zhǎo jīhuì zuòduō, xiàdiē qūshì lǐ zhǎo jīhuì zuòkōng, jǐnliàng búyào nìshì chāodǐ.","alternative_answers":[],"segments":[{"who":null,"zh":"顺势交易的意思是跟着趋势走：","pinyin":"Shùnshì jiāoyì de yìsi shì gēnzhe qūshì zǒu:","vi":"Giao dịch thuận xu hướng nghĩa là đi theo xu hướng:","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"上涨趋势里找机会做多，下跌趋势里找机会做空，尽量不要逆势抄底。","pinyin":"Shàngzhǎng qūshì lǐ zhǎo jīhuì zuòduō, xiàdiē qūshì lǐ zhǎo jīhuì zuòkōng, jǐnliàng búyào nìshì chāodǐ.","vi":"trong xu hướng tăng thì tìm cơ hội Long, trong xu hướng giảm thì tìm cơ hội Short, cố gắng không bắt đáy ngược xu hướng.","alt_zh":[],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"顺势","pinyin":"shùnshì","meaning_vi":"thuận xu hướng","hsk30_level":"7-9","specialized":false},{"word":"跟着","pinyin":"gēnzhe","meaning_vi":"đi theo","hsk30_level":null,"specialized":true},{"word":"机会","pinyin":"jīhuì","meaning_vi":"cơ hội","hsk30_level":3,"specialized":false},{"word":"尽量","pinyin":"jǐnliàng","meaning_vi":"cố gắng hết mức","hsk30_level":5,"specialized":false},{"word":"逆势","pinyin":"nìshì","meaning_vi":"ngược xu hướng","hsk30_level":null,"specialized":true},{"word":"抄底","pinyin":"chāodǐ","meaning_vi":"bắt đáy","hsk30_level":null,"specialized":true}],"grammar_notes":["…的意思是…: \"… nghĩa là…\".","尽量不要: \"cố gắng đừng…\"."],"term_notes":[{"term":"顺势 / 逆势","explain":"Trend following (thuận xu hướng) và counter-trend (ngược xu hướng)."},{"term":"抄底","explain":"Bắt đáy: mua khi giá đang giảm với kỳ vọng đã chạm đáy."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"strategy","set":"crypto-trading-50"},{"id":"w3t-39","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"vi-zh","hsk30_level":4,"hsk30_basis":"manual","hsk20_level":null,"title":"Quy tắc rủi ro 1–2%","context":null,"roles":null,"prompt":"Nhiều trader mỗi lệnh chỉ chấp nhận rủi ro tối đa 1% đến 2% tổng vốn. Như vậy dù thua liên tiếp vài lần, tài khoản cũng không bị ảnh hưởng quá nhiều.","answer":"很多交易者每笔交易最多只冒总资金百分之一到百分之二的风险。这样即使连续亏几次，账户也不会受到太大的影响。","pinyin":"Hěn duō jiāoyìzhě měi bǐ jiāoyì zuìduō zhǐ mào zǒng zījīn bǎifēnzhīyī dào bǎifēnzhī'èr de fēngxiǎn. Zhèyàng jíshǐ liánxù kuī jǐcì, zhànghù yě búhuì shòudào tài dà de yǐngxiǎng.","alternative_answers":[],"segments":[{"who":null,"zh":"很多交易者每笔交易最多只冒总资金百分之一到百分之二的风险。","pinyin":"Hěn duō jiāoyìzhě měi bǐ jiāoyì zuìduō zhǐ mào zǒng zījīn bǎifēnzhīyī dào bǎifēnzhī'èr de fēngxiǎn.","vi":"Nhiều trader mỗi lệnh chỉ chấp nhận rủi ro tối đa 1% đến 2% tổng vốn.","alt_zh":[{"zh":"很多交易者每笔交易最多只承担总资金1%到2%的风险。","pinyin":"Hěn duō jiāoyìzhě měi bǐ jiāoyì zuìduō zhǐ chéngdān zǒng zījīn 1% dào 2% de fēngxiǎn.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"这样即使连续亏几次，账户也不会受到太大的影响。","pinyin":"Zhèyàng jíshǐ liánxù kuī jǐcì, zhànghù yě búhuì shòudào tài dà de yǐngxiǎng.","vi":"Như vậy dù thua liên tiếp vài lần, tài khoản cũng không bị ảnh hưởng quá nhiều.","alt_zh":[{"zh":"这样就算连亏几次，账户也不会受到太大影响。","pinyin":"Zhèyàng jiùsuàn lián kuī jǐcì, zhànghù yě búhuì shòudào tài dà yǐngxiǎng.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"交易者","pinyin":"jiāoyìzhě","meaning_vi":"trader, người giao dịch","hsk30_level":null,"specialized":true},{"word":"冒风险","pinyin":"mào fēngxiǎn","meaning_vi":"chấp nhận rủi ro","hsk30_level":null,"specialized":true},{"word":"总资金","pinyin":"zǒng zījīn","meaning_vi":"tổng vốn","hsk30_level":null,"specialized":true},{"word":"百分之","pinyin":"bǎi fēnzhī","meaning_vi":"phần trăm","hsk30_level":null,"specialized":true},{"word":"连续","pinyin":"liánxù","meaning_vi":"liên tiếp","hsk30_level":5,"specialized":false},{"word":"受到影响","pinyin":"shòudào yǐngxiǎng","meaning_vi":"bị ảnh hưởng","hsk30_level":null,"specialized":true}],"grammar_notes":["冒…的风险: \"chịu rủi ro…\".","百分之一: cách đọc 1% trong tiếng Trung (phần trăm đứng trước số)."],"term_notes":[{"term":"仓位管理","explain":"Quản lý vị thế (position sizing): quyết định mỗi lệnh dùng bao nhiêu vốn để một lần thua không làm hỏng tài khoản."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"risk","set":"crypto-trading-50"},{"id":"w3t-45","topic_id":"web3","subtopic_id":"web3.bitcoin","exercise_type":"sentence","direction":"vi-zh","hsk30_level":3,"hsk30_basis":"manual","hsk20_level":null,"title":"Thị trường giảm mạnh","context":null,"roles":null,"prompt":"Hôm nay thị trường crypto giảm mạnh.","answer":"今天加密市场大跌。","pinyin":"Jīntiān jiāmì shìchǎng dàdiē.","alternative_answers":[],"segments":[{"who":null,"zh":"今天加密市场大跌。","pinyin":"Jīntiān jiāmì shìchǎng dàdiē.","vi":"Hôm nay thị trường crypto giảm mạnh.","alt_zh":[{"zh":"今天币圈大跌。","pinyin":"Jīntiān bìquān dàdiē.","note":"Cách dịch tương đương"},{"zh":"今天加密货币市场大幅下跌。","pinyin":"Jīntiān jiāmì huòbì shìchǎng dàfú xiàdiē.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"加密市场","pinyin":"jiāmì shìchǎng","meaning_vi":"thị trường crypto","hsk30_level":null,"specialized":true},{"word":"大跌","pinyin":"dàdiē","meaning_vi":"giảm mạnh","hsk30_level":null,"specialized":true},{"word":"币圈","pinyin":"bìquān","meaning_vi":"giới crypto (khẩu ngữ)","hsk30_level":null,"specialized":true}],"grammar_notes":["大 + động từ (大跌, 大涨): \"… mạnh\", cách nói ngắn trong tin tức."],"term_notes":[{"term":"币圈","explain":"\"Vòng tròn coin\": cách gọi khẩu ngữ giới/thị trường crypto ở Trung Quốc."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"news","set":"crypto-trading-50"},{"id":"w3t-46","topic_id":"web3","subtopic_id":"web3.exchange","exercise_type":"paragraph","direction":"zh-vi","hsk30_level":4,"hsk30_basis":"manual","hsk20_level":null,"title":"Niêm yết coin mới","context":null,"roles":null,"prompt":"某交易所今天宣布，将于明天下午四点上线一个新币，并开放现货交易。为了庆祝上线，平台还推出了交易赛活动。","answer":"Một sàn giao dịch hôm nay thông báo sẽ niêm yết một đồng coin mới vào 4 giờ chiều mai và mở giao dịch spot. Để chào mừng việc niêm yết, nền tảng còn tung ra sự kiện thi đấu giao dịch.","pinyin":"Mǒu jiāoyìsuǒ jīntiān xuānbù, jiāng yú míngtiān xiàwǔ sì diǎn shàngxiàn yí gè xīn bì, bìng kāifàng xiànhuò jiāoyì. Wèile qìngzhù shàngxiàn, píngtái hái tuīchū le jiāoyìsài huódòng.","alternative_answers":[],"segments":[{"who":null,"zh":"某交易所今天宣布，将于明天下午四点上线一个新币，并开放现货交易。","pinyin":"Mǒu jiāoyìsuǒ jīntiān xuānbù, jiāng yú míngtiān xiàwǔ sì diǎn shàngxiàn yí gè xīn bì, bìng kāifàng xiànhuò jiāoyì.","vi":"Một sàn giao dịch hôm nay thông báo sẽ niêm yết một đồng coin mới vào 4 giờ chiều mai và mở giao dịch spot.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"为了庆祝上线，平台还推出了交易赛活动。","pinyin":"Wèile qìngzhù shàngxiàn, píngtái hái tuīchū le jiāoyìsài huódòng.","vi":"Để chào mừng việc niêm yết, nền tảng còn tung ra sự kiện thi đấu giao dịch.","alt_zh":[],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"宣布","pinyin":"xuānbù","meaning_vi":"tuyên bố, thông báo","hsk30_level":5,"specialized":false},{"word":"将于","pinyin":"jiāng yú","meaning_vi":"sẽ vào (lúc)","hsk30_level":null,"specialized":true},{"word":"上线","pinyin":"shàngxiàn","meaning_vi":"niêm yết, ra mắt","hsk30_level":null,"specialized":true},{"word":"开放","pinyin":"kāifàng","meaning_vi":"mở","hsk30_level":5,"specialized":false},{"word":"庆祝","pinyin":"qìngzhù","meaning_vi":"chúc mừng","hsk30_level":4,"specialized":false},{"word":"推出","pinyin":"tuīchū","meaning_vi":"tung ra","hsk30_level":4,"specialized":false},{"word":"交易赛","pinyin":"jiāoyìsài","meaning_vi":"cuộc thi giao dịch","hsk30_level":null,"specialized":true}],"grammar_notes":["将于 + thời gian + động từ: \"sẽ… vào…\", văn thông báo.","某: \"một… nào đó\", không nêu tên cụ thể."],"term_notes":[{"term":"上线 / 上币","explain":"Niêm yết coin lên sàn (listing). Ngược lại là 下架 (hủy niêm yết)."},{"term":"交易赛","explain":"Trading competition: sự kiện thưởng cho người có khối lượng hoặc lợi nhuận cao, thường dùng khi niêm yết coin mới."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"news","set":"crypto-trading-50"}];
window.TR_PACKS["w3t-b56"]=[{"id":"w3t-04","topic_id":"web3","subtopic_id":"web3.basics","exercise_type":"paragraph","direction":"zh-vi","hsk30_level":5,"hsk30_basis":"manual","hsk20_level":null,"title":"Blockchain hoạt động thế nào?","context":null,"roles":null,"prompt":"区块链是一种公开的分布式账本。每一笔交易都会被记录在区块里，区块按时间顺序连接起来。数据一旦上链，就很难被修改。","answer":"Blockchain là một sổ cái phân tán công khai. Mỗi giao dịch đều được ghi vào các khối, và các khối được nối với nhau theo thứ tự thời gian. Dữ liệu một khi đã được đưa lên chuỗi thì rất khó bị sửa đổi.","pinyin":"Qūkuàiliàn shì yìzhǒng gōngkāi de fēnbùshì zhàngběn. Měi yì bǐ jiāoyì dōu huì bèi jìlù zài qūkuài lǐ, qūkuài àn shíjiān shùnxù liánjiē qǐlai. Shùjù yídàn shàngliàn, jiù hěn nán bèi xiūgǎi.","alternative_answers":[],"segments":[{"who":null,"zh":"区块链是一种公开的分布式账本。","pinyin":"Qūkuàiliàn shì yìzhǒng gōngkāi de fēnbùshì zhàngběn.","vi":"Blockchain là một sổ cái phân tán công khai.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"每一笔交易都会被记录在区块里，区块按时间顺序连接起来。","pinyin":"Měi yì bǐ jiāoyì dōu huì bèi jìlù zài qūkuài lǐ, qūkuài àn shíjiān shùnxù liánjiē qǐlai.","vi":"Mỗi giao dịch đều được ghi vào các khối, và các khối được nối với nhau theo thứ tự thời gian.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"数据一旦上链，就很难被修改。","pinyin":"Shùjù yídàn shàngliàn, jiù hěn nán bèi xiūgǎi.","vi":"Dữ liệu một khi đã được đưa lên chuỗi thì rất khó bị sửa đổi.","alt_zh":[],"alt_vi":[{"vi":"Dữ liệu đã lên blockchain thì gần như không thể bị chỉnh sửa.","note":"Cách dịch tương đương"}],"avoid_zh":[]}],"vocabulary":[{"word":"分布式","pinyin":"fēnbùshì","meaning_vi":"phân tán","hsk30_level":null,"specialized":true},{"word":"账本","pinyin":"zhàngběn","meaning_vi":"sổ cái","hsk30_level":null,"specialized":true},{"word":"笔","pinyin":"bǐ","meaning_vi":"lượng từ cho giao dịch, khoản tiền","hsk30_level":2,"specialized":false},{"word":"区块","pinyin":"qūkuài","meaning_vi":"khối (block)","hsk30_level":null,"specialized":true},{"word":"顺序","pinyin":"shùnxù","meaning_vi":"thứ tự","hsk30_level":4,"specialized":false},{"word":"修改","pinyin":"xiūgǎi","meaning_vi":"sửa đổi","hsk30_level":5,"specialized":false}],"grammar_notes":["一旦…就…: \"một khi… thì…\", nêu điều kiện dẫn đến kết quả gần như chắc chắn.","被记录 / 被修改: câu bị động; tiếng Việt có thể dịch \"được ghi\", \"bị sửa\"."],"term_notes":[{"term":"上链","explain":"\"Đưa lên chuỗi\": ghi dữ liệu vào blockchain."},{"term":"分布式账本","explain":"Sổ cái phân tán: nhiều máy (nút) cùng giữ một bản sao sổ cái, không do một bên duy nhất quản lý."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"basic","set":"crypto-trading-50"},{"id":"w3t-05","topic_id":"web3","subtopic_id":"web3.wallet","exercise_type":"paragraph","direction":"vi-zh","hsk30_level":6,"hsk30_basis":"manual","hsk20_level":null,"title":"Ví nóng và ví lạnh","context":null,"roles":null,"prompt":"Ví nóng luôn kết nối Internet, dùng tiện lợi nhưng rủi ro bảo mật tương đối cao. Ví lạnh lưu khóa riêng ngoại tuyến, phù hợp hơn để cất giữ tài sản lớn lâu dài. Dù dùng loại ví nào, cũng đừng nói cụm từ khôi phục cho bất kỳ ai.","answer":"热钱包一直连接互联网，使用方便，但安全风险相对较高。冷钱包把私钥离线保存，更适合长期存放大额资产。无论使用哪种钱包，都不要把助记词告诉任何人。","pinyin":"Rè qiánbāo yìzhí liánjiē hùliánwǎng, shǐyòng fāngbiàn, dàn ānquán fēngxiǎn xiāngduì jiào gāo. Lěng qiánbāo bǎ sīyào líxiàn bǎocún, gèng shìhé chángqī cúnfàng dà'é zīchǎn. Wúlùn shǐyòng nǎ zhǒng qiánbāo, dōu búyào bǎ zhùjìcí gàosu rènhé rén.","alternative_answers":[],"segments":[{"who":null,"zh":"热钱包一直连接互联网，使用方便，但安全风险相对较高。","pinyin":"Rè qiánbāo yìzhí liánjiē hùliánwǎng, shǐyòng fāngbiàn, dàn ānquán fēngxiǎn xiāngduì jiào gāo.","vi":"Ví nóng luôn kết nối Internet, dùng tiện lợi nhưng rủi ro bảo mật tương đối cao.","alt_zh":[{"zh":"热钱包始终连着网络，用起来方便，但安全风险比较高。","pinyin":"Rè qiánbāo shǐzhōng lián zhe wǎngluò, yòng qǐlai fāngbiàn, dàn ānquán fēngxiǎn bǐjiào gāo.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"冷钱包把私钥离线保存，更适合长期存放大额资产。","pinyin":"Lěng qiánbāo bǎ sīyào líxiàn bǎocún, gèng shìhé chángqī cúnfàng dà'é zīchǎn.","vi":"Ví lạnh lưu khóa riêng ngoại tuyến, phù hợp hơn để cất giữ tài sản lớn lâu dài.","alt_zh":[{"zh":"冷钱包离线保存私钥，更适合长期存放大额资产。","pinyin":"Lěng qiánbāo líxiàn bǎocún sīyào, gèng shìhé chángqī cúnfàng dà'é zīchǎn.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"无论使用哪种钱包，都不要把助记词告诉任何人。","pinyin":"Wúlùn shǐyòng nǎ zhǒng qiánbāo, dōu búyào bǎ zhùjìcí gàosu rènhé rén.","vi":"Dù dùng loại ví nào, cũng đừng nói cụm từ khôi phục cho bất kỳ ai.","alt_zh":[{"zh":"不管用哪种钱包，都不要把助记词告诉别人。","pinyin":"Bùguǎn yòng nǎ zhǒng qiánbāo, dōu búyào bǎ zhùjìcí gàosu biéren.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"热钱包","pinyin":"rè qiánbāo","meaning_vi":"ví nóng","hsk30_level":null,"specialized":true},{"word":"冷钱包","pinyin":"lěng qiánbāo","meaning_vi":"ví lạnh","hsk30_level":null,"specialized":true},{"word":"私钥","pinyin":"sīyào","meaning_vi":"khóa riêng (private key)","hsk30_level":null,"specialized":true},{"word":"离线","pinyin":"líxiàn","meaning_vi":"ngoại tuyến","hsk30_level":null,"specialized":true},{"word":"大额","pinyin":"dà'é","meaning_vi":"số tiền lớn","hsk30_level":null,"specialized":true},{"word":"助记词","pinyin":"zhùjìcí","meaning_vi":"cụm từ khôi phục (seed phrase)","hsk30_level":null,"specialized":true}],"grammar_notes":["无论…都…: \"dù… đều/cũng…\", kết quả không đổi trong mọi trường hợp.","把 + tân ngữ + 告诉 + người: câu chữ 把 đưa đối tượng bị tác động (助记词) lên trước động từ."],"term_notes":[{"term":"助记词","explain":"Seed phrase: 12 hoặc 24 từ dùng để khôi phục ví. Ai có cụm từ này thì kiểm soát được toàn bộ tài sản trong ví."},{"term":"热钱包 / 冷钱包","explain":"Ví nóng luôn trực tuyến (ví app, ví trên sàn); ví lạnh giữ khóa ngoại tuyến (ví cứng, ví giấy)."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Thuật ngữ ví đối chiếu với trang \"Ví\" của ethereum.org (bản tiếng Trung). Câu văn tự biên soạn. Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"basic","set":"crypto-trading-50"},{"id":"w3t-10","topic_id":"web3","subtopic_id":"web3.exchange","exercise_type":"paragraph","direction":"zh-vi","hsk30_level":5,"hsk30_basis":"manual","hsk20_level":null,"title":"Rút coin chọn sai mạng","context":null,"roles":null,"prompt":"提币之前，一定要确认提币地址和网络是否一致。如果选错了网络，资产可能无法到账，甚至永久丢失。建议第一次提币时先小额测试。","answer":"Trước khi rút coin, nhất định phải kiểm tra địa chỉ rút và mạng lưới có khớp nhau không. Nếu chọn sai mạng, tài sản có thể không về được, thậm chí mất vĩnh viễn. Lần đầu rút coin nên thử trước với một khoản nhỏ.","pinyin":"Tíbì zhīqián, yídìng yào quèrèn tíbì dìzhǐ hé wǎngluò shìfǒu yízhì. Rúguǒ xuǎn cuò le wǎngluò, zīchǎn kěnéng wúfǎ dàozhàng, shènzhì yǒngjiǔ diūshī. Jiànyì dì yícì tíbì shí xiān xiǎo'é cèshì.","alternative_answers":[],"segments":[{"who":null,"zh":"提币之前，一定要确认提币地址和网络是否一致。","pinyin":"Tíbì zhīqián, yídìng yào quèrèn tíbì dìzhǐ hé wǎngluò shìfǒu yízhì.","vi":"Trước khi rút coin, nhất định phải kiểm tra địa chỉ rút và mạng lưới có khớp nhau không.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"如果选错了网络，资产可能无法到账，甚至永久丢失。","pinyin":"Rúguǒ xuǎn cuò le wǎngluò, zīchǎn kěnéng wúfǎ dàozhàng, shènzhì yǒngjiǔ diūshī.","vi":"Nếu chọn sai mạng, tài sản có thể không về được, thậm chí mất vĩnh viễn.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"建议第一次提币时先小额测试。","pinyin":"Jiànyì dì yícì tíbì shí xiān xiǎo'é cèshì.","vi":"Lần đầu rút coin nên thử trước với một khoản nhỏ.","alt_zh":[],"alt_vi":[{"vi":"Khi rút lần đầu, nên chuyển thử một số tiền nhỏ trước.","note":"Cách dịch tương đương"}],"avoid_zh":[]}],"vocabulary":[{"word":"确认","pinyin":"quèrèn","meaning_vi":"xác nhận, kiểm tra lại","hsk30_level":5,"specialized":false},{"word":"地址","pinyin":"dìzhǐ","meaning_vi":"địa chỉ (ví)","hsk30_level":4,"specialized":false},{"word":"网络","pinyin":"wǎngluò","meaning_vi":"mạng lưới (chain)","hsk30_level":5,"specialized":false},{"word":"一致","pinyin":"yízhì","meaning_vi":"khớp, thống nhất","hsk30_level":5,"specialized":false},{"word":"甚至","pinyin":"shènzhì","meaning_vi":"thậm chí","hsk30_level":4,"specialized":false},{"word":"永久","pinyin":"yǒngjiǔ","meaning_vi":"vĩnh viễn","hsk30_level":"7-9","specialized":false},{"word":"小额","pinyin":"xiǎo'é","meaning_vi":"số tiền nhỏ","hsk30_level":null,"specialized":true}],"grammar_notes":["是否: \"có… hay không\", văn viết của 是不是.","选错: động từ + bổ ngữ kết quả 错 = làm sai."],"term_notes":[{"term":"网络 (提币网络)","explain":"Mạng lưới khi rút, ví dụ USDT có thể rút qua TRC20, ERC20, BEP20. Ví nhận phải hỗ trợ đúng mạng đó."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"exchange","set":"crypto-trading-50"},{"id":"w3t-15","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"vi-zh","hsk30_level":5,"hsk30_basis":"manual","hsk20_level":null,"title":"Đầu tư định kỳ (DCA)","context":null,"roles":null,"prompt":"Đầu tư định kỳ (DCA) là một chiến lược spot khá đơn giản. Nhà đầu tư mua cùng một tài sản với số tiền cố định mỗi tuần hoặc mỗi tháng, không cần đoán đáy, có thể giảm rủi ro mua một lần ở vùng giá cao.","answer":"定投是一种比较简单的现货策略。投资者每周或每月用固定金额买入同一种资产，不用猜测最低点，可以降低一次性买在高位的风险。","pinyin":"Dìngtóu shì yìzhǒng bǐjiào jiǎndān de xiànhuò cèlüè. Tóuzīzhě měizhōu huò měiyuè yòng gùdìng jīn'é mǎirù tóngyī zhǒng zīchǎn, búyòng cāicè zuìdīdiǎn, kěyǐ jiàngdī yícìxìng mǎi zài gāowèi de fēngxiǎn.","alternative_answers":[],"segments":[{"who":null,"zh":"定投是一种比较简单的现货策略。","pinyin":"Dìngtóu shì yìzhǒng bǐjiào jiǎndān de xiànhuò cèlüè.","vi":"Đầu tư định kỳ (DCA) là một chiến lược spot khá đơn giản.","alt_zh":[{"zh":"定投是一种相对简单的现货策略。","pinyin":"Dìngtóu shì yìzhǒng xiāngduì jiǎndān de xiànhuò cèlüè.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"投资者每周或每月用固定金额买入同一种资产，不用猜测最低点，可以降低一次性买在高位的风险。","pinyin":"Tóuzīzhě měizhōu huò měiyuè yòng gùdìng jīn'é mǎirù tóngyī zhǒng zīchǎn, búyòng cāicè zuìdīdiǎn, kěyǐ jiàngdī yícìxìng mǎi zài gāowèi de fēngxiǎn.","vi":"Nhà đầu tư mua cùng một tài sản với số tiền cố định mỗi tuần hoặc mỗi tháng, không cần đoán đáy, có thể giảm rủi ro mua một lần ở vùng giá cao.","alt_zh":[{"zh":"投资者每周或每个月用固定的金额买入同一种资产，不需要猜底，可以降低一次买在高点的风险。","pinyin":"Tóuzīzhě měizhōu huò měi gè yuè yòng gùdìng de jīn'é mǎirù tóngyī zhǒng zīchǎn, bù xūyào cāidǐ, kěyǐ jiàngdī yícì mǎi zài gāo diǎn de fēngxiǎn.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"定投","pinyin":"dìngtóu","meaning_vi":"đầu tư định kỳ","hsk30_level":null,"specialized":true},{"word":"策略","pinyin":"cèlüè","meaning_vi":"chiến lược","hsk30_level":6,"specialized":false},{"word":"固定","pinyin":"gùdìng","meaning_vi":"cố định","hsk30_level":5,"specialized":false},{"word":"金额","pinyin":"jīn'é","meaning_vi":"số tiền","hsk30_level":6,"specialized":false},{"word":"猜测","pinyin":"cāicè","meaning_vi":"đoán","hsk30_level":6,"specialized":false},{"word":"降低","pinyin":"jiàngdī","meaning_vi":"giảm","hsk30_level":4,"specialized":false},{"word":"高位","pinyin":"gāowèi","meaning_vi":"vùng giá cao","hsk30_level":null,"specialized":true}],"grammar_notes":["不用 + động từ: \"không cần…\".","一次性: \"một lần (gộp)\", tính từ đứng trước động từ làm trạng ngữ."],"term_notes":[{"term":"定投 (DCA)","explain":"Dollar-Cost Averaging: chia vốn mua đều theo thời gian để có giá trung bình, giảm tác động của việc mua sai thời điểm."},{"term":"抄底 / 追高","explain":"抄底 = bắt đáy; 追高 = mua đuổi giá cao. DCA giúp tránh cả hai kiểu đoán thị trường."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"spot","set":"crypto-trading-50"},{"id":"w3t-18","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"zh-vi","hsk30_level":5,"hsk30_basis":"manual","hsk20_level":null,"title":"Funding rate dương","context":null,"roles":null,"prompt":"当资金费率为正时，做多的用户需要向做空的用户支付资金费用。资金费率长期偏高，通常说明市场上做多的人太多，情绪过热。","answer":"Khi funding rate dương, người mở Long phải trả phí funding cho người mở Short. Funding rate cao kéo dài thường cho thấy trên thị trường có quá nhiều người Long, tâm lý quá hưng phấn.","pinyin":"Dāng zījīn fèilǜ wéizhèng shí, zuòduō de yònghù xūyào xiàng zuòkōng de yònghù zhīfù zījīn fèiyòng. Zījīn fèilǜ chángqī piāngāo, tōngcháng shuōmíng shìchǎng shàng zuòduō de rén tài duō, qíngxù guòrè.","alternative_answers":[],"segments":[{"who":null,"zh":"当资金费率为正时，做多的用户需要向做空的用户支付资金费用。","pinyin":"Dāng zījīn fèilǜ wéizhèng shí, zuòduō de yònghù xūyào xiàng zuòkōng de yònghù zhīfù zījīn fèiyòng.","vi":"Khi funding rate dương, người mở Long phải trả phí funding cho người mở Short.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"资金费率长期偏高，通常说明市场上做多的人太多，情绪过热。","pinyin":"Zījīn fèilǜ chángqī piāngāo, tōngcháng shuōmíng shìchǎng shàng zuòduō de rén tài duō, qíngxù guòrè.","vi":"Funding rate cao kéo dài thường cho thấy trên thị trường có quá nhiều người Long, tâm lý quá hưng phấn.","alt_zh":[],"alt_vi":[{"vi":"Funding rate cao trong thời gian dài thường là dấu hiệu phe Long quá đông, thị trường đang quá nóng.","note":"Cách dịch tương đương"}],"avoid_zh":[]}],"vocabulary":[{"word":"资金费率","pinyin":"zījīn fèilǜ","meaning_vi":"funding rate","hsk30_level":null,"specialized":true},{"word":"为正","pinyin":"wéizhèng","meaning_vi":"dương","hsk30_level":null,"specialized":true},{"word":"支付","pinyin":"zhīfù","meaning_vi":"thanh toán, trả","hsk30_level":4,"specialized":false},{"word":"偏高","pinyin":"piāngāo","meaning_vi":"hơi cao, cao","hsk30_level":null,"specialized":true},{"word":"说明","pinyin":"shuōmíng","meaning_vi":"cho thấy","hsk30_level":4,"specialized":false},{"word":"情绪","pinyin":"qíngxù","meaning_vi":"tâm lý","hsk30_level":5,"specialized":false},{"word":"过热","pinyin":"guòrè","meaning_vi":"quá nóng","hsk30_level":null,"specialized":true}],"grammar_notes":["当…时: \"khi…\", văn viết của …的时候.","向 + người + 支付: \"trả cho ai\"."],"term_notes":[{"term":"资金费率","explain":"Funding rate dương: Long trả Short; âm: Short trả Long. Chỉ số này thường dùng để đo tâm lý đòn bẩy của thị trường."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"futures","set":"crypto-trading-50"},{"id":"w3t-19","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"vi-zh","hsk30_level":5,"hsk30_basis":"manual","hsk20_level":null,"title":"Thanh lý (cháy tài khoản)","context":null,"roles":null,"prompt":"Nếu giá đi theo hướng bất lợi và ký quỹ không đủ để duy trì vị thế, hệ thống sẽ đóng vị thế bắt buộc, đó chính là cháy tài khoản (thanh lý). Đòn bẩy càng cao thì càng gần giá thanh lý.","answer":"如果价格向不利方向变动，保证金不足以维持仓位，系统就会强制平仓，这就是爆仓。杠杆越高，离强平价格就越近。","pinyin":"Rúguǒ jiàgé xiàng búlì fāngxiàng biàndòng, bǎozhèngjīn bù zúyǐ wéichí cāngwèi, xìtǒng jiù huì qiángzhì píngcāng, zhè jiùshì bàocāng. Gànggǎn yuè gāo, lí qiángpíng jiàgé jiù yuè jìn.","alternative_answers":[],"segments":[{"who":null,"zh":"如果价格向不利方向变动，保证金不足以维持仓位，系统就会强制平仓，这就是爆仓。","pinyin":"Rúguǒ jiàgé xiàng búlì fāngxiàng biàndòng, bǎozhèngjīn bù zúyǐ wéichí cāngwèi, xìtǒng jiù huì qiángzhì píngcāng, zhè jiùshì bàocāng.","vi":"Nếu giá đi theo hướng bất lợi và ký quỹ không đủ để duy trì vị thế, hệ thống sẽ đóng vị thế bắt buộc, đó chính là cháy tài khoản (thanh lý).","alt_zh":[{"zh":"如果价格往不利的方向走，保证金不够维持仓位，系统就会强平，这就是爆仓。","pinyin":"Rúguǒ jiàgé wǎng búlì de fāngxiàng zǒu, bǎozhèngjīn búgòu wéichí cāngwèi, xìtǒng jiù huì qiángpíng, zhè jiùshì bàocāng.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"杠杆越高，离强平价格就越近。","pinyin":"Gànggǎn yuè gāo, lí qiángpíng jiàgé jiù yuè jìn.","vi":"Đòn bẩy càng cao thì càng gần giá thanh lý.","alt_zh":[{"zh":"杠杆越大，离强平价就越近。","pinyin":"Gànggǎn yuè dà, lí qiángpíng jià jiù yuè jìn.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"不利","pinyin":"búlì","meaning_vi":"bất lợi","hsk30_level":5,"specialized":false},{"word":"保证金","pinyin":"bǎozhèngjīn","meaning_vi":"ký quỹ","hsk30_level":null,"specialized":true},{"word":"不足以","pinyin":"bù zúyǐ","meaning_vi":"không đủ để","hsk30_level":null,"specialized":true},{"word":"维持","pinyin":"wéichí","meaning_vi":"duy trì","hsk30_level":5,"specialized":false},{"word":"强制平仓","pinyin":"qiángzhì píngcāng","meaning_vi":"đóng vị thế bắt buộc","hsk30_level":null,"specialized":true},{"word":"爆仓","pinyin":"bàocāng","meaning_vi":"cháy tài khoản","hsk30_level":null,"specialized":true},{"word":"杠杆","pinyin":"gànggǎn","meaning_vi":"đòn bẩy","hsk30_level":"7-9","specialized":false}],"grammar_notes":["不足以 + động từ: \"không đủ để…\", văn viết.","越…越…: \"càng… càng…\".","离 + điểm mốc + 近/远: \"cách… gần/xa\"."],"term_notes":[{"term":"强平 / 爆仓","explain":"强平 (强制平仓) là thao tác hệ thống tự đóng vị thế khi ký quỹ không đủ; 爆仓 là cách nói khẩu ngữ cho việc bị thanh lý, mất phần lớn hoặc toàn bộ ký quỹ."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"futures","set":"crypto-trading-50"},{"id":"w3t-20","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"zh-vi","hsk30_level":6,"hsk30_basis":"manual","hsk20_level":null,"title":"Giá đánh dấu","context":null,"roles":null,"prompt":"为了避免因为短时间的价格操纵而触发强平，很多交易所使用标记价格来计算未实现盈亏和强平价格。标记价格通常参考多个现货交易所的指数价格。","answer":"Để tránh bị thanh lý do giá bị thao túng trong thời gian ngắn, nhiều sàn dùng giá đánh dấu để tính lãi lỗ chưa thực hiện và giá thanh lý. Giá đánh dấu thường tham chiếu giá chỉ số của nhiều sàn giao ngay.","pinyin":"Wèile bìmiǎn yīnwèi duǎn shíjiān de jiàgé cāozòng ér chùfā qiángpíng, hěn duō jiāoyìsuǒ shǐyòng biāojì jiàgé lái jìsuàn wèi shíxiàn yíngkuī hé qiángpíng jiàgé. Biāojì jiàgé tōngcháng cānkǎo duōgè xiànhuò jiāoyìsuǒ de zhǐshù jiàgé.","alternative_answers":[],"segments":[{"who":null,"zh":"为了避免因为短时间的价格操纵而触发强平，很多交易所使用标记价格来计算未实现盈亏和强平价格。","pinyin":"Wèile bìmiǎn yīnwèi duǎn shíjiān de jiàgé cāozòng ér chùfā qiángpíng, hěn duō jiāoyìsuǒ shǐyòng biāojì jiàgé lái jìsuàn wèi shíxiàn yíngkuī hé qiángpíng jiàgé.","vi":"Để tránh bị thanh lý do giá bị thao túng trong thời gian ngắn, nhiều sàn dùng giá đánh dấu để tính lãi lỗ chưa thực hiện và giá thanh lý.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"标记价格通常参考多个现货交易所的指数价格。","pinyin":"Biāojì jiàgé tōngcháng cānkǎo duōgè xiànhuò jiāoyìsuǒ de zhǐshù jiàgé.","vi":"Giá đánh dấu thường tham chiếu giá chỉ số của nhiều sàn giao ngay.","alt_zh":[],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"避免","pinyin":"bìmiǎn","meaning_vi":"tránh","hsk30_level":5,"specialized":false},{"word":"操纵","pinyin":"cāozòng","meaning_vi":"thao túng","hsk30_level":"7-9","specialized":false},{"word":"触发","pinyin":"chùfā","meaning_vi":"kích hoạt","hsk30_level":null,"specialized":true},{"word":"标记价格","pinyin":"biāojì jiàgé","meaning_vi":"giá đánh dấu","hsk30_level":null,"specialized":true},{"word":"未实现盈亏","pinyin":"wèi shíxiàn yíngkuī","meaning_vi":"lãi lỗ chưa thực hiện","hsk30_level":null,"specialized":true},{"word":"参考","pinyin":"cānkǎo","meaning_vi":"tham chiếu","hsk30_level":5,"specialized":false},{"word":"指数价格","pinyin":"zhǐshù jiàgé","meaning_vi":"giá chỉ số","hsk30_level":null,"specialized":true}],"grammar_notes":["因为…而…: \"vì… mà…\", văn viết.","使用…来…: \"dùng… để…\"."],"term_notes":[{"term":"标记价格","explain":"Mark price: giá dùng để tính lãi lỗ chưa thực hiện và thanh lý, giúp tránh bị thanh lý oan do một cây nến bất thường."},{"term":"未实现盈亏","explain":"Unrealized PnL: lãi lỗ tạm tính của vị thế đang mở; chỉ thành lãi lỗ thực (已实现盈亏) khi đóng vị thế."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"futures","set":"crypto-trading-50"},{"id":"w3t-22","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"dialogue","direction":"zh-vi","hsk30_level":6,"hsk30_basis":"manual","hsk20_level":null,"title":"Trao đổi về lệnh Short","context":"Hai trader nói chuyện trong nhóm chat.","roles":{"A":"trader A","B":"trader B"},"prompt":"你现在还拿着那个空单吗？\n早上已经平了一半，剩下的设了止损。\n资金费率一直是负的，空头太拥挤了，小心轧空。\n明白，如果突破前高，我就全部止损出场。","answer":"Bạn vẫn đang giữ lệnh Short đó à?\nSáng nay đã đóng một nửa rồi, phần còn lại đã đặt cắt lỗ.\nFunding rate liên tục âm, phe Short quá đông rồi, cẩn thận bị short squeeze.\nHiểu rồi, nếu phá đỉnh cũ thì tôi sẽ cắt lỗ thoát hết.","pinyin":"Nǐ xiànzài hái ná zhe nàge kōngdān ma? Zǎoshang yǐjīng píng le yíbàn, shèngxià de shè le zhǐsǔn. Zījīn fèilǜ yìzhí shì fù de, kōngtóu tài yōngjǐ le, xiǎoxīn gákōng. Míngbai, rúguǒ tūpò qiángāo, wǒ jiù quánbù zhǐsǔn chūchǎng.","alternative_answers":[],"segments":[{"who":"A","zh":"你现在还拿着那个空单吗？","pinyin":"Nǐ xiànzài hái ná zhe nàge kōngdān ma?","vi":"Bạn vẫn đang giữ lệnh Short đó à?","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":"B","zh":"早上已经平了一半，剩下的设了止损。","pinyin":"Zǎoshang yǐjīng píng le yíbàn, shèngxià de shè le zhǐsǔn.","vi":"Sáng nay đã đóng một nửa rồi, phần còn lại đã đặt cắt lỗ.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":"A","zh":"资金费率一直是负的，空头太拥挤了，小心轧空。","pinyin":"Zījīn fèilǜ yìzhí shì fù de, kōngtóu tài yōngjǐ le, xiǎoxīn gákōng.","vi":"Funding rate liên tục âm, phe Short quá đông rồi, cẩn thận bị short squeeze.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":"B","zh":"明白，如果突破前高，我就全部止损出场。","pinyin":"Míngbai, rúguǒ tūpò qiángāo, wǒ jiù quánbù zhǐsǔn chūchǎng.","vi":"Hiểu rồi, nếu phá đỉnh cũ thì tôi sẽ cắt lỗ thoát hết.","alt_zh":[],"alt_vi":[{"vi":"Rõ rồi, nếu giá vượt đỉnh trước tôi sẽ cắt lỗ đóng toàn bộ.","note":"Cách dịch tương đương"}],"avoid_zh":[]}],"vocabulary":[{"word":"拿着","pinyin":"ná zhe","meaning_vi":"đang giữ","hsk30_level":null,"specialized":true},{"word":"空单","pinyin":"kōngdān","meaning_vi":"lệnh Short","hsk30_level":null,"specialized":true},{"word":"平","pinyin":"píng","meaning_vi":"đóng (vị thế)","hsk30_level":5,"specialized":false},{"word":"止损","pinyin":"zhǐsǔn","meaning_vi":"cắt lỗ","hsk30_level":null,"specialized":true},{"word":"拥挤","pinyin":"yōngjǐ","meaning_vi":"đông đúc, chen chúc","hsk30_level":6,"specialized":false},{"word":"轧空","pinyin":"gákōng","meaning_vi":"short squeeze","hsk30_level":null,"specialized":true},{"word":"突破","pinyin":"tūpò","meaning_vi":"phá vỡ","hsk30_level":6,"specialized":false},{"word":"前高","pinyin":"qiángāo","meaning_vi":"đỉnh trước","hsk30_level":null,"specialized":true}],"grammar_notes":["动词 + 着 (拿着): trạng thái đang kéo dài.","剩下的: \"phần còn lại\", 的 biến cụm động từ thành danh từ.","如果…就…: \"nếu… thì…\"."],"term_notes":[{"term":"轧空","explain":"Short squeeze: phe Short quá đông, giá tăng khiến họ bị thanh lý hoặc buộc phải mua lại, đẩy giá tăng tiếp. Còn gọi 逼空; khẩu ngữ hay viết 嘎空 (gā kōng)."},{"term":"出场","explain":"\"Ra khỏi thị trường\": đóng vị thế. Ngược lại là 入场 (vào lệnh)."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"futures","set":"crypto-trading-50"},{"id":"w3t-25","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"vi-zh","hsk30_level":5,"hsk30_basis":"manual","hsk20_level":null,"title":"Ký quỹ chéo và ký quỹ cô lập","context":null,"roles":null,"prompt":"Ở chế độ ký quỹ chéo, toàn bộ số dư khả dụng trong tài khoản đều được dùng làm ký quỹ, một vị thế thua lỗ có thể ảnh hưởng tới các vị thế khác. Ở chế độ ký quỹ cô lập, ký quỹ của mỗi vị thế là độc lập, lỗ tối đa chỉ giới hạn ở phần ký quỹ của vị thế đó.","answer":"全仓模式下，账户里所有可用余额都会作为保证金，一个仓位亏损可能影响其他仓位。逐仓模式下，每个仓位的保证金是独立的，最大亏损只限于这个仓位的保证金。","pinyin":"Quáncāng móshì xià, zhànghù lǐ suǒyǒu kěyòng yú'é dōu huì zuòwéi bǎozhèngjīn, yí gè cāngwèi kuīsǔn kěnéng yǐngxiǎng qítā cāngwèi. Zhúcāng móshì xià, měi gè cāngwèi de bǎozhèngjīn shì dúlì de, zuì dà kuīsǔn zhǐ xiànyú zhège cāngwèi de bǎozhèngjīn.","alternative_answers":[],"segments":[{"who":null,"zh":"全仓模式下，账户里所有可用余额都会作为保证金，一个仓位亏损可能影响其他仓位。","pinyin":"Quáncāng móshì xià, zhànghù lǐ suǒyǒu kěyòng yú'é dōu huì zuòwéi bǎozhèngjīn, yí gè cāngwèi kuīsǔn kěnéng yǐngxiǎng qítā cāngwèi.","vi":"Ở chế độ ký quỹ chéo, toàn bộ số dư khả dụng trong tài khoản đều được dùng làm ký quỹ, một vị thế thua lỗ có thể ảnh hưởng tới các vị thế khác.","alt_zh":[{"zh":"在全仓模式下，账户中全部可用余额都作为保证金，一个仓位的亏损可能会影响其他仓位。","pinyin":"Zài quáncāng móshì xià, zhànghù zhōng quánbù kěyòng yú'é dōu zuòwéi bǎozhèngjīn, yí gè cāngwèi de kuīsǔn kěnéng huì yǐngxiǎng qítā cāngwèi.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"逐仓模式下，每个仓位的保证金是独立的，最大亏损只限于这个仓位的保证金。","pinyin":"Zhúcāng móshì xià, měi gè cāngwèi de bǎozhèngjīn shì dúlì de, zuì dà kuīsǔn zhǐ xiànyú zhège cāngwèi de bǎozhèngjīn.","vi":"Ở chế độ ký quỹ cô lập, ký quỹ của mỗi vị thế là độc lập, lỗ tối đa chỉ giới hạn ở phần ký quỹ của vị thế đó.","alt_zh":[{"zh":"在逐仓模式下，每个仓位的保证金互相独立，最多只会亏掉该仓位的保证金。","pinyin":"Zài zhúcāng móshì xià, měi gè cāngwèi de bǎozhèngjīn hùxiāng dúlì, zuìduō zhǐ huì kuī diào gāi cāngwèi de bǎozhèngjīn.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"全仓","pinyin":"quáncāng","meaning_vi":"ký quỹ chéo (cross)","hsk30_level":null,"specialized":true},{"word":"逐仓","pinyin":"zhúcāng","meaning_vi":"ký quỹ cô lập (isolated)","hsk30_level":null,"specialized":true},{"word":"模式","pinyin":"móshì","meaning_vi":"chế độ","hsk30_level":5,"specialized":false},{"word":"可用余额","pinyin":"kěyòng yú'é","meaning_vi":"số dư khả dụng","hsk30_level":null,"specialized":true},{"word":"亏损","pinyin":"kuīsǔn","meaning_vi":"thua lỗ","hsk30_level":6,"specialized":false},{"word":"独立","pinyin":"dúlì","meaning_vi":"độc lập","hsk30_level":5,"specialized":false},{"word":"限于","pinyin":"xiànyú","meaning_vi":"giới hạn ở","hsk30_level":6,"specialized":false}],"grammar_notes":["…模式下: \"ở chế độ…\", cụm trạng ngữ đặt đầu câu.","只限于: \"chỉ giới hạn trong…\"."],"term_notes":[{"term":"全仓 / 逐仓","explain":"Cross margin dùng chung toàn bộ số dư để giữ vị thế (khó bị thanh lý hơn nhưng có thể mất cả tài khoản); isolated margin tách riêng ký quỹ cho từng vị thế."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"margin","set":"crypto-trading-50"},{"id":"w3t-26","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"zh-vi","hsk30_level":5,"hsk30_basis":"manual","hsk20_level":null,"title":"Đặt chốt lời và cắt lỗ","context":null,"roles":null,"prompt":"止损单是在价格跌到某个位置时自动卖出的订单。设好止损以后，即使你不在电脑前，也能控制亏损。很多交易者在开仓的同时就会设置止盈和止损。","answer":"Lệnh cắt lỗ là lệnh tự động bán khi giá giảm đến một mức nhất định. Đặt sẵn cắt lỗ rồi thì dù bạn không ngồi trước máy tính vẫn kiểm soát được thua lỗ. Nhiều trader đặt luôn chốt lời và cắt lỗ ngay khi mở vị thế.","pinyin":"Zhǐsǔndān shì zài jiàgé diē dào mǒu gè wèizhì shí zìdòng màichū de dìngdān. Shè hǎo zhǐsǔn yǐhòu, jíshǐ nǐ búzài diànnǎo qián, yě néng kòngzhì kuīsǔn. Hěn duō jiāoyìzhě zài kāicāng de tóngshí jiù huì shèzhì zhǐyíng hé zhǐsǔn.","alternative_answers":[],"segments":[{"who":null,"zh":"止损单是在价格跌到某个位置时自动卖出的订单。","pinyin":"Zhǐsǔndān shì zài jiàgé diē dào mǒu gè wèizhì shí zìdòng màichū de dìngdān.","vi":"Lệnh cắt lỗ là lệnh tự động bán khi giá giảm đến một mức nhất định.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"设好止损以后，即使你不在电脑前，也能控制亏损。","pinyin":"Shè hǎo zhǐsǔn yǐhòu, jíshǐ nǐ búzài diànnǎo qián, yě néng kòngzhì kuīsǔn.","vi":"Đặt sẵn cắt lỗ rồi thì dù bạn không ngồi trước máy tính vẫn kiểm soát được thua lỗ.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"很多交易者在开仓的同时就会设置止盈和止损。","pinyin":"Hěn duō jiāoyìzhě zài kāicāng de tóngshí jiù huì shèzhì zhǐyíng hé zhǐsǔn.","vi":"Nhiều trader đặt luôn chốt lời và cắt lỗ ngay khi mở vị thế.","alt_zh":[],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"止损单","pinyin":"zhǐsǔndān","meaning_vi":"lệnh cắt lỗ","hsk30_level":null,"specialized":true},{"word":"某个","pinyin":"mǒu gè","meaning_vi":"một… nào đó","hsk30_level":null,"specialized":true},{"word":"自动","pinyin":"zìdòng","meaning_vi":"tự động","hsk30_level":5,"specialized":false},{"word":"即使…也…","pinyin":"jíshǐ… yě…","meaning_vi":"dù… cũng…","hsk30_level":null,"specialized":true},{"word":"开仓","pinyin":"kāicāng","meaning_vi":"mở vị thế","hsk30_level":null,"specialized":true},{"word":"同时","pinyin":"tóngshí","meaning_vi":"đồng thời","hsk30_level":4,"specialized":false},{"word":"止盈","pinyin":"zhǐyíng","meaning_vi":"chốt lời","hsk30_level":null,"specialized":true}],"grammar_notes":["即使…也…: \"dù… cũng…\", giả định nhượng bộ.","在…的同时: \"cùng lúc với…\".","设好: động từ + bổ ngữ kết quả 好 = làm xong, làm sẵn."],"term_notes":[{"term":"止盈 / 止损","explain":"Take Profit (TP) và Stop Loss (SL): hai lệnh điều kiện tự đóng vị thế khi giá chạm mức chốt lời hoặc cắt lỗ."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"margin","set":"crypto-trading-50"},{"id":"w3t-30","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"zh-vi","hsk30_level":5,"hsk30_basis":"manual","hsk20_level":null,"title":"Chỉ báo RSI","context":null,"roles":null,"prompt":"RSI是常用的动量指标，数值在0到100之间。一般认为RSI高于70是超买，低于30是超卖，但在强势行情中，指标可能长时间停留在超买区。","answer":"RSI là chỉ báo động lượng thường dùng, giá trị nằm trong khoảng 0 đến 100. Thường cho rằng RSI trên 70 là quá mua, dưới 30 là quá bán, nhưng trong xu hướng mạnh, chỉ báo có thể nằm lâu trong vùng quá mua.","pinyin":"RSI shì chángyòng de dòngliàng zhǐbiāo, shùzhí zài 0 dào 100 zhījiān. Yìbān rènwéi RSI gāoyú 70 shì chāomǎi, dīyú 30 shì chāomài, dàn zài qiángshì hángqíng zhōng, zhǐbiāo kěnéng cháng shíjiān tíngliú zài chāomǎi qū.","alternative_answers":[],"segments":[{"who":null,"zh":"RSI是常用的动量指标，数值在0到100之间。","pinyin":"RSI shì chángyòng de dòngliàng zhǐbiāo, shùzhí zài 0 dào 100 zhījiān.","vi":"RSI là chỉ báo động lượng thường dùng, giá trị nằm trong khoảng 0 đến 100.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"一般认为RSI高于70是超买，低于30是超卖，但在强势行情中，指标可能长时间停留在超买区。","pinyin":"Yìbān rènwéi RSI gāoyú 70 shì chāomǎi, dīyú 30 shì chāomài, dàn zài qiángshì hángqíng zhōng, zhǐbiāo kěnéng cháng shíjiān tíngliú zài chāomǎi qū.","vi":"Thường cho rằng RSI trên 70 là quá mua, dưới 30 là quá bán, nhưng trong xu hướng mạnh, chỉ báo có thể nằm lâu trong vùng quá mua.","alt_zh":[],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"动量","pinyin":"dòngliàng","meaning_vi":"động lượng","hsk30_level":null,"specialized":true},{"word":"指标","pinyin":"zhǐbiāo","meaning_vi":"chỉ báo","hsk30_level":"7-9","specialized":false},{"word":"数值","pinyin":"shùzhí","meaning_vi":"giá trị","hsk30_level":null,"specialized":true},{"word":"超买","pinyin":"chāomǎi","meaning_vi":"quá mua","hsk30_level":null,"specialized":true},{"word":"超卖","pinyin":"chāomài","meaning_vi":"quá bán","hsk30_level":null,"specialized":true},{"word":"行情","pinyin":"hángqíng","meaning_vi":"diễn biến thị trường","hsk30_level":"7-9","specialized":false},{"word":"停留","pinyin":"tíngliú","meaning_vi":"dừng lại, nằm lại","hsk30_level":5,"specialized":false}],"grammar_notes":["在…之间: \"trong khoảng…\".","一般认为: \"thường cho rằng\", chủ ngữ ẩn."],"term_notes":[{"term":"RSI","explain":"Relative Strength Index: chỉ số sức mạnh tương đối, đo tốc độ và độ lớn của biến động giá."},{"term":"行情","explain":"\"Diễn biến thị trường\": 强势行情 = thị trường mạnh, 震荡行情 = đi ngang, 牛市 / 熊市 = thị trường bò / gấu."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"ta","set":"crypto-trading-50"},{"id":"w3t-31","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"vi-zh","hsk30_level":5,"hsk30_basis":"manual","hsk20_level":null,"title":"Đường trung bình và giao cắt vàng","context":null,"roles":null,"prompt":"Đường trung bình động giúp xác định hướng xu hướng. Khi đường trung bình ngắn hạn cắt lên trên đường trung bình dài hạn từ phía dưới thì gọi là giao cắt vàng, thường được xem là tín hiệu mua; ngược lại gọi là giao cắt tử thần.","answer":"均线可以帮助判断趋势方向。当短期均线从下方向上穿过长期均线时，叫做金叉，常被看作买入信号；反过来叫死叉。","pinyin":"Jūnxiàn kěyǐ bāngzhù pànduàn qūshì fāngxiàng. Dāng duǎnqī jūnxiàn cóng xiàfāng xiàngshàng chuānguò chángqī jūnxiàn shí, jiàozuò jīnchā, cháng bèi kànzuò mǎirù xìnhào; fǎnguòlái jiào sǐchā.","alternative_answers":[],"segments":[{"who":null,"zh":"均线可以帮助判断趋势方向。","pinyin":"Jūnxiàn kěyǐ bāngzhù pànduàn qūshì fāngxiàng.","vi":"Đường trung bình động giúp xác định hướng xu hướng.","alt_zh":[{"zh":"移动平均线可以帮助判断趋势的方向。","pinyin":"Yídòng píngjūnxiàn kěyǐ bāngzhù pànduàn qūshì de fāngxiàng.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"当短期均线从下方向上穿过长期均线时，叫做金叉，常被看作买入信号；反过来叫死叉。","pinyin":"Dāng duǎnqī jūnxiàn cóng xiàfāng xiàngshàng chuānguò chángqī jūnxiàn shí, jiàozuò jīnchā, cháng bèi kànzuò mǎirù xìnhào; fǎnguòlái jiào sǐchā.","vi":"Khi đường trung bình ngắn hạn cắt lên trên đường trung bình dài hạn từ phía dưới thì gọi là giao cắt vàng, thường được xem là tín hiệu mua; ngược lại gọi là giao cắt tử thần.","alt_zh":[{"zh":"短期均线由下往上穿过长期均线时叫金叉，通常被视为买入信号；相反的情况叫死叉。","pinyin":"Duǎnqī jūnxiàn yóu xià wǎng shàng chuānguò chángqī jūnxiàn shí jiào jīnchā, tōngcháng bèi shìwéi mǎirù xìnhào; xiāngfǎn de qíngkuàng jiào sǐchā.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"均线","pinyin":"jūnxiàn","meaning_vi":"đường trung bình động","hsk30_level":null,"specialized":true},{"word":"判断","pinyin":"pànduàn","meaning_vi":"phán đoán, xác định","hsk30_level":4,"specialized":false},{"word":"趋势","pinyin":"qūshì","meaning_vi":"xu hướng","hsk30_level":5,"specialized":false},{"word":"穿过","pinyin":"chuānguò","meaning_vi":"cắt qua","hsk30_level":6,"specialized":false},{"word":"金叉","pinyin":"jīnchā","meaning_vi":"giao cắt vàng","hsk30_level":null,"specialized":true},{"word":"信号","pinyin":"xìnhào","meaning_vi":"tín hiệu","hsk30_level":4,"specialized":false},{"word":"死叉","pinyin":"sǐchā","meaning_vi":"giao cắt tử thần","hsk30_level":null,"specialized":true}],"grammar_notes":["被看作: \"được xem là\", bị động.","从…向…: \"từ… hướng về…\"."],"term_notes":[{"term":"金叉 / 死叉","explain":"Golden cross và death cross: tín hiệu giao cắt giữa đường trung bình ngắn hạn và dài hạn."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"ta","set":"crypto-trading-50"},{"id":"w3t-32","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"zh-vi","hsk30_level":6,"hsk30_basis":"manual","hsk20_level":null,"title":"Khối lượng xác nhận phá vỡ","context":null,"roles":null,"prompt":"突破的时候要关注成交量。如果价格放量突破阻力位，突破的可信度更高；如果缩量突破，很可能只是假突破，价格随后又跌回区间内。","answer":"Khi giá phá vỡ cần chú ý khối lượng giao dịch. Nếu giá phá kháng cự với khối lượng tăng mạnh thì độ tin cậy cao hơn; nếu phá vỡ với khối lượng thấp thì rất có thể chỉ là phá vỡ giả, sau đó giá lại rơi về trong vùng đi ngang.","pinyin":"Tūpò de shíhou yào guānzhù chéngjiāo liàng. Rúguǒ jiàgé fàngliàng tūpò zǔlìwèi, tūpò de kěxìn dù gèng gāo; Rúguǒ suōliàng tūpò, hěn kěnéng zhǐshì jiǎ tūpò, jiàgé suíhòu yòu diēhuí qūjiān nèi.","alternative_answers":[],"segments":[{"who":null,"zh":"突破的时候要关注成交量。","pinyin":"Tūpò de shíhou yào guānzhù chéngjiāo liàng.","vi":"Khi giá phá vỡ cần chú ý khối lượng giao dịch.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"如果价格放量突破阻力位，突破的可信度更高；","pinyin":"Rúguǒ jiàgé fàngliàng tūpò zǔlìwèi, tūpò de kěxìn dù gèng gāo;","vi":"Nếu giá phá kháng cự với khối lượng tăng mạnh thì độ tin cậy cao hơn;","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"如果缩量突破，很可能只是假突破，价格随后又跌回区间内。","pinyin":"Rúguǒ suōliàng tūpò, hěn kěnéng zhǐshì jiǎ tūpò, jiàgé suíhòu yòu diēhuí qūjiān nèi.","vi":"nếu phá vỡ với khối lượng thấp thì rất có thể chỉ là phá vỡ giả, sau đó giá lại rơi về trong vùng đi ngang.","alt_zh":[],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"关注","pinyin":"guānzhù","meaning_vi":"chú ý, theo dõi","hsk30_level":3,"specialized":false},{"word":"成交量","pinyin":"chéngjiāo liàng","meaning_vi":"khối lượng giao dịch","hsk30_level":null,"specialized":true},{"word":"放量","pinyin":"fàngliàng","meaning_vi":"khối lượng tăng","hsk30_level":null,"specialized":true},{"word":"可信度","pinyin":"kěxìn dù","meaning_vi":"độ tin cậy","hsk30_level":null,"specialized":true},{"word":"缩量","pinyin":"suōliàng","meaning_vi":"khối lượng giảm","hsk30_level":null,"specialized":true},{"word":"假突破","pinyin":"jiǎ tūpò","meaning_vi":"phá vỡ giả","hsk30_level":null,"specialized":true},{"word":"区间","pinyin":"qūjiān","meaning_vi":"vùng (giá)","hsk30_level":"7-9","specialized":false}],"grammar_notes":["放量突破 / 缩量突破: trạng ngữ cách thức đứng trước động từ 突破.","跌回: động từ + bổ ngữ xu hướng 回 = \"rơi trở lại\"."],"term_notes":[{"term":"放量 / 缩量","explain":"Khối lượng tăng mạnh / giảm so với bình thường."},{"term":"假突破","explain":"Fakeout: giá vượt mốc rồi nhanh chóng quay lại, thường bẫy người mua đuổi."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"ta","set":"crypto-trading-50"},{"id":"w3t-35","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"vi-zh","hsk30_level":5,"hsk30_basis":"manual","hsk20_level":null,"title":"Giao dịch lưới (Grid)","context":null,"roles":null,"prompt":"Giao dịch lưới phù hợp với thị trường đi ngang. Người dùng đặt trước một khoảng giá, hệ thống sẽ chia nhiều lần mua thấp bán cao trong khoảng đó, tự động kiếm chênh lệch. Nhưng nếu giá rơi khỏi khoảng này thì có thể bị kẹt hàng.","answer":"网格交易适合震荡行情。用户先设定一个价格区间，系统会在区间内分批低买高卖，自动赚取差价。但如果价格跌破区间，就可能被套。","pinyin":"Wǎnggé jiāoyì shìhé zhèndàng hángqíng. Yònghù xiān shèdìng yí gè jiàgé qūjiān, xìtǒng huì zài qūjiān nèi fēnpī dīmǎigāomài, zìdòng zhuànqǔ chājià. Dàn rúguǒ jiàgé diēpò qūjiān, jiù kěnéng bèitào.","alternative_answers":[],"segments":[{"who":null,"zh":"网格交易适合震荡行情。","pinyin":"Wǎnggé jiāoyì shìhé zhèndàng hángqíng.","vi":"Giao dịch lưới phù hợp với thị trường đi ngang.","alt_zh":[{"zh":"网格交易比较适合震荡市。","pinyin":"Wǎnggé jiāoyì bǐjiào shìhé zhèndàng shì.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"用户先设定一个价格区间，系统会在区间内分批低买高卖，自动赚取差价。","pinyin":"Yònghù xiān shèdìng yí gè jiàgé qūjiān, xìtǒng huì zài qūjiān nèi fēnpī dīmǎigāomài, zìdòng zhuànqǔ chājià.","vi":"Người dùng đặt trước một khoảng giá, hệ thống sẽ chia nhiều lần mua thấp bán cao trong khoảng đó, tự động kiếm chênh lệch.","alt_zh":[{"zh":"用户先设置价格区间，系统就在这个区间里分批低买高卖，自动赚差价。","pinyin":"Yònghù xiān shèzhì jiàgé qūjiān, xìtǒng jiù zài zhège qūjiān lǐ fēnpī dīmǎigāomài, zìdòng zhuàn chājià.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"但如果价格跌破区间，就可能被套。","pinyin":"Dàn rúguǒ jiàgé diēpò qūjiān, jiù kěnéng bèitào.","vi":"Nhưng nếu giá rơi khỏi khoảng này thì có thể bị kẹt hàng.","alt_zh":[{"zh":"不过如果价格跌出区间，就有可能被套住。","pinyin":"Búguò rúguǒ jiàgé diē chū qūjiān, jiù yǒu kěnéng bèitào zhù.","note":"Cách dịch tương đương"}],"alt_vi":[{"vi":"Nhưng nếu giá thủng khoảng giá đã đặt, bạn có thể bị \"chôn vốn\".","note":"Cách dịch tương đương"}],"avoid_zh":[]}],"vocabulary":[{"word":"网格交易","pinyin":"wǎnggé jiāoyì","meaning_vi":"giao dịch lưới","hsk30_level":null,"specialized":true},{"word":"震荡","pinyin":"zhèndàng","meaning_vi":"dao động, đi ngang","hsk30_level":"7-9","specialized":false},{"word":"分批","pinyin":"fēnpī","meaning_vi":"chia nhiều đợt","hsk30_level":null,"specialized":true},{"word":"低买高卖","pinyin":"dīmǎigāomài","meaning_vi":"mua thấp bán cao","hsk30_level":null,"specialized":true},{"word":"差价","pinyin":"chājià","meaning_vi":"chênh lệch giá","hsk30_level":null,"specialized":true},{"word":"跌破","pinyin":"diēpò","meaning_vi":"giảm thủng","hsk30_level":null,"specialized":true},{"word":"被套","pinyin":"bèitào","meaning_vi":"bị kẹt hàng","hsk30_level":null,"specialized":true}],"grammar_notes":["先…，…: \"trước tiên… rồi…\".","跌破: động từ + bổ ngữ kết quả 破 = \"thủng (mốc)\"."],"term_notes":[{"term":"网格交易","explain":"Grid trading: bot đặt sẵn nhiều lệnh mua bán cách đều trong một khoảng giá."},{"term":"被套","explain":"Bị kẹt: mua ở giá cao, giá giảm sâu nên chưa thể bán mà không lỗ."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"strategy","set":"crypto-trading-50"},{"id":"w3t-36","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"zh-vi","hsk30_level":6,"hsk30_basis":"manual","hsk20_level":null,"title":"Copy trade","context":null,"roles":null,"prompt":"跟单交易可以让新手自动复制带单员的操作。不过，过去的收益率不代表未来表现，选择带单员时，除了看收益，还要看最大回撤和交易风格。","answer":"Copy trade cho phép người mới tự động sao chép thao tác của trader dẫn lệnh. Tuy nhiên, tỷ suất lợi nhuận trong quá khứ không đại diện cho kết quả tương lai; khi chọn trader dẫn lệnh, ngoài lợi nhuận còn phải xem mức sụt giảm tối đa và phong cách giao dịch.","pinyin":"Gēndān jiāoyì kěyǐ ràng xīnshǒu zìdòng fùzhì dàidānyuán de cāozuò. Búguò, guòqù de shōuyìlǜ bú dàibiǎo wèilái biǎoxiàn, Xuǎnzé dàidānyuán shí, chúle kàn shōuyì, hái yàokàn zuì dà huíchè hé jiāoyì fēnggé.","alternative_answers":[],"segments":[{"who":null,"zh":"跟单交易可以让新手自动复制带单员的操作。","pinyin":"Gēndān jiāoyì kěyǐ ràng xīnshǒu zìdòng fùzhì dàidānyuán de cāozuò.","vi":"Copy trade cho phép người mới tự động sao chép thao tác của trader dẫn lệnh.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"不过，过去的收益率不代表未来表现，","pinyin":"Búguò, guòqù de shōuyìlǜ bú dàibiǎo wèilái biǎoxiàn,","vi":"Tuy nhiên, tỷ suất lợi nhuận trong quá khứ không đại diện cho kết quả tương lai;","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"选择带单员时，除了看收益，还要看最大回撤和交易风格。","pinyin":"Xuǎnzé dàidānyuán shí, chúle kàn shōuyì, hái yàokàn zuì dà huíchè hé jiāoyì fēnggé.","vi":"khi chọn trader dẫn lệnh, ngoài lợi nhuận còn phải xem mức sụt giảm tối đa và phong cách giao dịch.","alt_zh":[],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"跟单","pinyin":"gēndān","meaning_vi":"copy lệnh","hsk30_level":null,"specialized":true},{"word":"新手","pinyin":"xīnshǒu","meaning_vi":"người mới","hsk30_level":"7-9","specialized":false},{"word":"复制","pinyin":"fùzhì","meaning_vi":"sao chép","hsk30_level":5,"specialized":false},{"word":"带单员","pinyin":"dàidānyuán","meaning_vi":"trader dẫn lệnh","hsk30_level":null,"specialized":true},{"word":"收益率","pinyin":"shōuyìlǜ","meaning_vi":"tỷ suất lợi nhuận","hsk30_level":null,"specialized":true},{"word":"最大回撤","pinyin":"zuì dà huíchè","meaning_vi":"mức sụt giảm tối đa","hsk30_level":null,"specialized":true},{"word":"风格","pinyin":"fēnggé","meaning_vi":"phong cách","hsk30_level":5,"specialized":false}],"grammar_notes":["除了…，还…: \"ngoài… ra còn…\".","不代表: \"không đại diện cho, không có nghĩa là\"."],"term_notes":[{"term":"带单员","explain":"Lead trader: người được sao chép lệnh, thường nhận chia lợi nhuận (分润) từ người copy."},{"term":"最大回撤","explain":"Max drawdown: mức giảm lớn nhất từ đỉnh xuống đáy của tài khoản, đo rủi ro thực tế của chiến lược."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"strategy","set":"crypto-trading-50"},{"id":"w3t-40","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"zh-vi","hsk30_level":5,"hsk30_basis":"manual","hsk20_level":null,"title":"Tỷ lệ lợi nhuận/rủi ro","context":null,"roles":null,"prompt":"开仓前最好先算好盈亏比。比如止损是两百美元，目标利润是六百美元，盈亏比就是一比三。盈亏比合理的话，胜率不高也有可能长期盈利。","answer":"Trước khi mở vị thế tốt nhất nên tính trước tỷ lệ lợi nhuận/rủi ro. Ví dụ cắt lỗ là 200 USD, lợi nhuận mục tiêu là 600 USD thì tỷ lệ là 1:3. Nếu tỷ lệ hợp lý, dù tỷ lệ thắng không cao vẫn có thể có lãi về lâu dài.","pinyin":"Kāicāng qián zuìhǎo xiān suàn hǎo yíngkuībǐ. Bǐrú zhǐsǔn shì liǎng bǎi měiyuán, mùbiāo lìrùn shì liù bǎi měiyuán, yíngkuībǐ jiùshì yì bǐ sān. Yíngkuībǐ hélǐ de huà, shènglǜ bù gāo yě yǒu kěnéng chángqī yínglì.","alternative_answers":[],"segments":[{"who":null,"zh":"开仓前最好先算好盈亏比。","pinyin":"Kāicāng qián zuìhǎo xiān suàn hǎo yíngkuībǐ.","vi":"Trước khi mở vị thế tốt nhất nên tính trước tỷ lệ lợi nhuận/rủi ro.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"比如止损是两百美元，目标利润是六百美元，盈亏比就是一比三。","pinyin":"Bǐrú zhǐsǔn shì liǎng bǎi měiyuán, mùbiāo lìrùn shì liù bǎi měiyuán, yíngkuībǐ jiùshì yì bǐ sān.","vi":"Ví dụ cắt lỗ là 200 USD, lợi nhuận mục tiêu là 600 USD thì tỷ lệ là 1:3.","alt_zh":[],"alt_vi":[{"vi":"Chẳng hạn mức cắt lỗ 200 đô, mục tiêu lãi 600 đô thì tỷ lệ rủi ro/lợi nhuận là 1:3.","note":"Cách dịch tương đương"}],"avoid_zh":[]},{"who":null,"zh":"盈亏比合理的话，胜率不高也有可能长期盈利。","pinyin":"Yíngkuībǐ hélǐ de huà, shènglǜ bù gāo yě yǒu kěnéng chángqī yínglì.","vi":"Nếu tỷ lệ hợp lý, dù tỷ lệ thắng không cao vẫn có thể có lãi về lâu dài.","alt_zh":[],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"最好","pinyin":"zuìhǎo","meaning_vi":"tốt nhất","hsk30_level":3,"specialized":false},{"word":"盈亏比","pinyin":"yíngkuībǐ","meaning_vi":"tỷ lệ lợi nhuận/rủi ro","hsk30_level":null,"specialized":true},{"word":"目标","pinyin":"mùbiāo","meaning_vi":"mục tiêu","hsk30_level":4,"specialized":false},{"word":"利润","pinyin":"lìrùn","meaning_vi":"lợi nhuận","hsk30_level":5,"specialized":false},{"word":"合理","pinyin":"hélǐ","meaning_vi":"hợp lý","hsk30_level":5,"specialized":false},{"word":"胜率","pinyin":"shènglǜ","meaning_vi":"tỷ lệ thắng","hsk30_level":null,"specialized":true},{"word":"盈利","pinyin":"yínglì","meaning_vi":"có lãi","hsk30_level":"7-9","specialized":false}],"grammar_notes":["…的话: \"nếu…\", đặt cuối vế điều kiện.","一比三: cách đọc tỷ lệ 1:3."],"term_notes":[{"term":"盈亏比","explain":"Risk/Reward ratio: so sánh khoản lỗ chấp nhận với khoản lãi kỳ vọng. Lưu ý thứ tự: 盈亏比 1:3 trong câu này là rủi ro 1, lợi nhuận 3."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"risk","set":"crypto-trading-50"},{"id":"w3t-41","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"vi-zh","hsk30_level":6,"hsk30_basis":"manual","hsk20_level":null,"title":"Tâm lý FOMO","context":null,"roles":null,"prompt":"Thấy người khác kiếm tiền liền vội vàng mua đuổi giá cao là nguyên nhân thua lỗ của nhiều người mới. Khi cảm xúc kích động, tốt nhất nên tạm dừng giao dịch, quay lại kế hoạch giao dịch của mình, thay vì tăng đòn bẩy để mong gỡ lại toàn bộ khoản lỗ một lần.","answer":"看到别人赚钱就急着追高，是很多新手亏损的原因。在情绪激动的时候，最好暂停交易，回到自己的交易计划，而不是加大杠杆想把亏损一次赚回来。","pinyin":"Kàn dào biéren zhuànqián jiù jízhe zhuīgāo, shì hěn duō xīnshǒu kuīsǔn de yuányīn. Zài qíngxù jīdòng de shíhou, zuìhǎo zàntíng jiāoyì, huídào zìjǐ de jiāoyì jìhuà, Ér búshì jiādà gànggǎn xiǎng bǎ kuīsǔn yícì zhuàn huílai.","alternative_answers":[],"segments":[{"who":null,"zh":"看到别人赚钱就急着追高，是很多新手亏损的原因。","pinyin":"Kàn dào biéren zhuànqián jiù jízhe zhuīgāo, shì hěn duō xīnshǒu kuīsǔn de yuányīn.","vi":"Thấy người khác kiếm tiền liền vội vàng mua đuổi giá cao là nguyên nhân thua lỗ của nhiều người mới.","alt_zh":[{"zh":"看见别人赚钱就着急追高，是不少新手亏钱的原因。","pinyin":"Kànjiàn biéren zhuànqián jiù zháojí zhuīgāo, shì bùshǎo xīnshǒu kuī qián de yuányīn.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"在情绪激动的时候，最好暂停交易，回到自己的交易计划，","pinyin":"Zài qíngxù jīdòng de shíhou, zuìhǎo zàntíng jiāoyì, huídào zìjǐ de jiāoyì jìhuà,","vi":"Khi cảm xúc kích động, tốt nhất nên tạm dừng giao dịch, quay lại kế hoạch giao dịch của mình,","alt_zh":[{"zh":"情绪激动时，最好先停止交易，回到自己的交易计划，","pinyin":"Qíngxù jīdòng shí, zuìhǎo xiān tíngzhǐ jiāoyì, huídào zìjǐ de jiāoyì jìhuà,","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"而不是加大杠杆想把亏损一次赚回来。","pinyin":"Ér búshì jiādà gànggǎn xiǎng bǎ kuīsǔn yícì zhuàn huílai.","vi":"thay vì tăng đòn bẩy để mong gỡ lại toàn bộ khoản lỗ một lần.","alt_zh":[{"zh":"而不是加杠杆想一次把亏的钱赚回来。","pinyin":"Ér búshì jiā gànggǎn xiǎng yícì bǎ kuī de qián zhuàn huílai.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"急着","pinyin":"jízhe","meaning_vi":"vội vàng","hsk30_level":null,"specialized":true},{"word":"追高","pinyin":"zhuīgāo","meaning_vi":"mua đuổi giá cao","hsk30_level":null,"specialized":true},{"word":"原因","pinyin":"yuányīn","meaning_vi":"nguyên nhân","hsk30_level":4,"specialized":false},{"word":"激动","pinyin":"jīdòng","meaning_vi":"kích động","hsk30_level":4,"specialized":false},{"word":"暂停","pinyin":"zàntíng","meaning_vi":"tạm dừng","hsk30_level":4,"specialized":false},{"word":"计划","pinyin":"jìhuà","meaning_vi":"kế hoạch","hsk30_level":4,"specialized":false},{"word":"加大","pinyin":"jiādà","meaning_vi":"tăng thêm","hsk30_level":null,"specialized":true}],"grammar_notes":["看到…就…: \"thấy… liền…\".","而不是…: \"chứ không phải…, thay vì…\".","赚回来: bổ ngữ xu hướng 回来 = \"lấy lại, gỡ lại\"."],"term_notes":[{"term":"FOMO","explain":"Fear of Missing Out – sợ bỏ lỡ; tiếng Trung thường nói 踏空焦虑 hoặc giữ nguyên FOMO."},{"term":"回本 / 上头","explain":"回本 = gỡ vốn; 上头 = \"lên máu\", giao dịch theo cảm xúc."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"risk","set":"crypto-trading-50"},{"id":"w3t-42","topic_id":"web3","subtopic_id":"web3.defi","exercise_type":"paragraph","direction":"zh-vi","hsk30_level":5,"hsk30_basis":"manual","hsk20_level":null,"title":"Sàn phi tập trung (DEX)","context":null,"roles":null,"prompt":"去中心化交易所不需要注册账户，用户直接用自己的钱包连接，通过智能合约完成兑换。资产一直由用户自己保管，但也要自己承担操作错误的风险。","answer":"Sàn phi tập trung không cần đăng ký tài khoản, người dùng kết nối trực tiếp bằng ví của mình và hoàn thành việc hoán đổi thông qua hợp đồng thông minh. Tài sản luôn do người dùng tự giữ, nhưng cũng phải tự chịu rủi ro thao tác sai.","pinyin":"Qùzhōngxīnhuà jiāoyìsuǒ bù xūyào zhùcè zhànghù, yònghù zhíjiē yòng zìjǐ de qiánbāo liánjiē, tōngguò zhìnéng héyuē wánchéng duìhuàn. Zīchǎn yìzhí yóu yònghù zìjǐ bǎoguǎn, dàn yě yào zìjǐ chéngdān cāozuò cuòwù de fēngxiǎn.","alternative_answers":[],"segments":[{"who":null,"zh":"去中心化交易所不需要注册账户，用户直接用自己的钱包连接，通过智能合约完成兑换。","pinyin":"Qùzhōngxīnhuà jiāoyìsuǒ bù xūyào zhùcè zhànghù, yònghù zhíjiē yòng zìjǐ de qiánbāo liánjiē, tōngguò zhìnéng héyuē wánchéng duìhuàn.","vi":"Sàn phi tập trung không cần đăng ký tài khoản, người dùng kết nối trực tiếp bằng ví của mình và hoàn thành việc hoán đổi thông qua hợp đồng thông minh.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"资产一直由用户自己保管，但也要自己承担操作错误的风险。","pinyin":"Zīchǎn yìzhí yóu yònghù zìjǐ bǎoguǎn, dàn yě yào zìjǐ chéngdān cāozuò cuòwù de fēngxiǎn.","vi":"Tài sản luôn do người dùng tự giữ, nhưng cũng phải tự chịu rủi ro thao tác sai.","alt_zh":[],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"去中心化","pinyin":"qùzhōngxīnhuà","meaning_vi":"phi tập trung","hsk30_level":null,"specialized":true},{"word":"注册","pinyin":"zhùcè","meaning_vi":"đăng ký","hsk30_level":5,"specialized":false},{"word":"连接","pinyin":"liánjiē","meaning_vi":"kết nối","hsk30_level":5,"specialized":false},{"word":"智能合约","pinyin":"zhìnéng héyuē","meaning_vi":"hợp đồng thông minh","hsk30_level":null,"specialized":true},{"word":"兑换","pinyin":"duìhuàn","meaning_vi":"hoán đổi, đổi","hsk30_level":"7-9","specialized":false},{"word":"保管","pinyin":"bǎoguǎn","meaning_vi":"bảo quản, giữ","hsk30_level":6,"specialized":false},{"word":"承担","pinyin":"chéngdān","meaning_vi":"gánh chịu","hsk30_level":5,"specialized":false}],"grammar_notes":["通过…完成…: \"hoàn thành… thông qua…\".","由 + người + động từ: \"do ai làm\"."],"term_notes":[{"term":"DEX","explain":"Decentralized Exchange: giao dịch trực tiếp từ ví, không giữ tài sản hộ người dùng, ví dụ Uniswap."},{"term":"兑换 / Swap","explain":"Hoán đổi token này sang token khác."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Thuật ngữ đối chiếu với trang DeFi và hướng dẫn \"Cách hoán đổi token\" của ethereum.org (bản tiếng Trung). Câu văn tự biên soạn. Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"defi","set":"crypto-trading-50"},{"id":"w3t-43","topic_id":"web3","subtopic_id":"web3.defi","exercise_type":"paragraph","direction":"vi-zh","hsk30_level":6,"hsk30_basis":"manual","hsk20_level":null,"title":"Pool thanh khoản và tổn thất tạm thời","context":null,"roles":null,"prompt":"Người dùng gửi hai loại token vào pool thanh khoản thì có thể được chia phí giao dịch. Tuy nhiên, nếu giá hai token thay đổi nhiều, có thể xảy ra tổn thất tạm thời, lợi nhuận cuối cùng chưa chắc cao hơn việc chỉ nắm giữ.","answer":"用户把两种代币存入流动性池，就能分到交易手续费。不过，如果两种代币的价格变化很大，可能会出现无常损失，最后的收益不一定比单纯持有更高。","pinyin":"Yònghù bǎ liǎng zhǒng dàibì cúnrù liúdòngxìng chí, jiù néng fēndào jiāoyì shǒuxùfèi. Búguò, rúguǒ liǎng zhǒng dàibì de jiàgé biànhuà hěn dà, kěnéng huì chūxiàn wúcháng sǔnshī, zuìhòu de shōuyì bù yídìng bǐ dānchún chíyǒu gèng gāo.","alternative_answers":[],"segments":[{"who":null,"zh":"用户把两种代币存入流动性池，就能分到交易手续费。","pinyin":"Yònghù bǎ liǎng zhǒng dàibì cúnrù liúdòngxìng chí, jiù néng fēndào jiāoyì shǒuxùfèi.","vi":"Người dùng gửi hai loại token vào pool thanh khoản thì có thể được chia phí giao dịch.","alt_zh":[{"zh":"用户将两种代币存进流动性池，就可以分得交易手续费。","pinyin":"Yònghù jiāng liǎng zhǒng dàibì cún jìn liúdòngxìng chí, jiù kěyǐ fēndé jiāoyì shǒuxùfèi.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"不过，如果两种代币的价格变化很大，可能会出现无常损失，最后的收益不一定比单纯持有更高。","pinyin":"Búguò, rúguǒ liǎng zhǒng dàibì de jiàgé biànhuà hěn dà, kěnéng huì chūxiàn wúcháng sǔnshī, zuìhòu de shōuyì bù yídìng bǐ dānchún chíyǒu gèng gāo.","vi":"Tuy nhiên, nếu giá hai token thay đổi nhiều, có thể xảy ra tổn thất tạm thời, lợi nhuận cuối cùng chưa chắc cao hơn việc chỉ nắm giữ.","alt_zh":[{"zh":"不过如果两种代币价格变动很大，就可能产生无常损失，最终收益未必比单纯持有高。","pinyin":"Búguò rúguǒ liǎng zhǒng dàibì jiàgé biàndòng hěn dà, jiù kěnéng chǎnshēng wúcháng sǔnshī, zuìzhōng shōuyì wèibì bǐ dānchún chíyǒu gāo.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"存入","pinyin":"cúnrù","meaning_vi":"gửi vào","hsk30_level":null,"specialized":true},{"word":"流动性池","pinyin":"liúdòngxìng chí","meaning_vi":"pool thanh khoản","hsk30_level":null,"specialized":true},{"word":"分到","pinyin":"fēndào","meaning_vi":"được chia","hsk30_level":null,"specialized":true},{"word":"无常损失","pinyin":"wúcháng sǔnshī","meaning_vi":"tổn thất tạm thời","hsk30_level":null,"specialized":true},{"word":"不一定","pinyin":"bù yídìng","meaning_vi":"chưa chắc","hsk30_level":null,"specialized":true},{"word":"单纯","pinyin":"dānchún","meaning_vi":"đơn thuần","hsk30_level":6,"specialized":false},{"word":"持有","pinyin":"chíyǒu","meaning_vi":"nắm giữ","hsk30_level":6,"specialized":false}],"grammar_notes":["把…存入…: câu chữ 把 với bổ ngữ 入 chỉ hướng \"vào\".","不一定比…更…: \"chưa chắc… hơn…\"."],"term_notes":[{"term":"流动性池","explain":"Liquidity pool: kho token do người dùng góp, cho phép DEX hoán đổi tự động."},{"term":"无常损失","explain":"Impermanent loss: phần thiệt so với chỉ giữ token, xảy ra khi tỷ giá hai token trong pool thay đổi."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"defi","set":"crypto-trading-50"},{"id":"w3t-47","topic_id":"web3","subtopic_id":"web3.bitcoin","exercise_type":"paragraph","direction":"vi-zh","hsk30_level":5,"hsk30_basis":"manual","hsk20_level":null,"title":"ETF Bitcoin có dòng vốn vào","context":null,"roles":null,"prompt":"Quỹ ETF Bitcoin giao ngay ghi nhận dòng vốn ròng chảy vào ba ngày liên tiếp, tâm lý thị trường rõ ràng ấm lên. Giới phân tích cho rằng dòng vốn tổ chức tham gia khiến giá Bitcoin ổn định hơn.","answer":"比特币现货ETF连续三天出现资金净流入，市场情绪明显回暖。分析人士认为，机构资金的进入让比特币的价格更加稳定。","pinyin":"Bǐtèbì xiànhuò ETF liánxù sān tiān chūxiàn zījīn jìngliúrù, shìchǎng qíngxù míngxiǎn huínuǎn. Fēnxī rénshì rènwéi, jīgòu zījīn de jìnrù ràng bǐtèbì de jiàgé gèngjiā wěndìng.","alternative_answers":[],"segments":[{"who":null,"zh":"比特币现货ETF连续三天出现资金净流入，市场情绪明显回暖。","pinyin":"Bǐtèbì xiànhuò ETF liánxù sān tiān chūxiàn zījīn jìngliúrù, shìchǎng qíngxù míngxiǎn huínuǎn.","vi":"Quỹ ETF Bitcoin giao ngay ghi nhận dòng vốn ròng chảy vào ba ngày liên tiếp, tâm lý thị trường rõ ràng ấm lên.","alt_zh":[{"zh":"比特币现货ETF已连续三天资金净流入，市场情绪明显好转。","pinyin":"Bǐtèbì xiànhuò ETF yǐ liánxù sān tiān zījīn jìngliúrù, shìchǎng qíngxù míngxiǎn hǎozhuǎn.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"分析人士认为，机构资金的进入让比特币的价格更加稳定。","pinyin":"Fēnxī rénshì rènwéi, jīgòu zījīn de jìnrù ràng bǐtèbì de jiàgé gèngjiā wěndìng.","vi":"Giới phân tích cho rằng dòng vốn tổ chức tham gia khiến giá Bitcoin ổn định hơn.","alt_zh":[{"zh":"分析师认为，机构资金入场使比特币价格更稳定。","pinyin":"Fēnxī shī rènwéi, jīgòu zījīn rùchǎng shǐ bǐtèbì jiàgé gèng wěndìng.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"现货ETF","pinyin":"xiànhuò ETF","meaning_vi":"ETF giao ngay","hsk30_level":null,"specialized":true},{"word":"净流入","pinyin":"jìngliúrù","meaning_vi":"dòng vốn ròng vào","hsk30_level":null,"specialized":true},{"word":"明显","pinyin":"míngxiǎn","meaning_vi":"rõ rệt","hsk30_level":5,"specialized":false},{"word":"回暖","pinyin":"huínuǎn","meaning_vi":"ấm lên","hsk30_level":null,"specialized":true},{"word":"分析人士","pinyin":"fēnxī rénshì","meaning_vi":"giới phân tích","hsk30_level":null,"specialized":true},{"word":"机构","pinyin":"jīgòu","meaning_vi":"tổ chức","hsk30_level":5,"specialized":false},{"word":"稳定","pinyin":"wěndìng","meaning_vi":"ổn định","hsk30_level":5,"specialized":false}],"grammar_notes":["连续 + số + 天: \"liên tiếp… ngày\".","让 + đối tượng + tính từ: \"khiến… trở nên…\"."],"term_notes":[{"term":"净流入 / 净流出","explain":"Dòng tiền vào trừ dòng tiền ra; số liệu ETF được giới crypto theo dõi hằng ngày."},{"term":"机构资金","explain":"Vốn tổ chức: quỹ đầu tư, công ty quản lý tài sản, khác nhà đầu tư cá nhân (散户)."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"news","set":"crypto-trading-50"},{"id":"w3t-48","topic_id":"web3","subtopic_id":"web3.bitcoin","exercise_type":"paragraph","direction":"zh-vi","hsk30_level":5,"hsk30_basis":"manual","hsk20_level":null,"title":"Thanh lý hàng loạt sau quyết định lãi suất","context":null,"roles":null,"prompt":"受美联储利率决议影响，比特币在一小时内下跌超过百分之五。数据显示，过去二十四小时全网爆仓金额超过五亿美元，其中多单占大部分。","answer":"Chịu ảnh hưởng của quyết định lãi suất của Fed, Bitcoin giảm hơn 5% trong vòng một giờ. Số liệu cho thấy trong 24 giờ qua, tổng giá trị bị thanh lý toàn thị trường vượt 500 triệu USD, trong đó phần lớn là lệnh Long.","pinyin":"Shòu Měiliánchǔ lìlǜ juéyì yǐngxiǎng, bǐtèbì zài yì xiǎoshí nèi xiàdiē chāoguò bǎifēnzhīwǔ. Shùjù xiǎnshì, guòqù èr shísì xiǎoshí quánwǎng bàocāng jīn'é chāoguò wǔ yì měiyuán, qízhōng duōdān zhàn dà bùfen.","alternative_answers":[],"segments":[{"who":null,"zh":"受美联储利率决议影响，比特币在一小时内下跌超过百分之五。","pinyin":"Shòu Měiliánchǔ lìlǜ juéyì yǐngxiǎng, bǐtèbì zài yì xiǎoshí nèi xiàdiē chāoguò bǎifēnzhīwǔ.","vi":"Chịu ảnh hưởng của quyết định lãi suất của Fed, Bitcoin giảm hơn 5% trong vòng một giờ.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"数据显示，过去二十四小时全网爆仓金额超过五亿美元，其中多单占大部分。","pinyin":"Shùjù xiǎnshì, guòqù èr shísì xiǎoshí quánwǎng bàocāng jīn'é chāoguò wǔ yì měiyuán, qízhōng duōdān zhàn dà bùfen.","vi":"Số liệu cho thấy trong 24 giờ qua, tổng giá trị bị thanh lý toàn thị trường vượt 500 triệu USD, trong đó phần lớn là lệnh Long.","alt_zh":[],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"受…影响","pinyin":"shòu… yǐngxiǎng","meaning_vi":"chịu ảnh hưởng của…","hsk30_level":null,"specialized":true},{"word":"美联储","pinyin":"Měiliánchǔ","meaning_vi":"Cục Dự trữ Liên bang Mỹ (Fed)","hsk30_level":null,"specialized":true},{"word":"利率","pinyin":"lìlǜ","meaning_vi":"lãi suất","hsk30_level":"7-9","specialized":false},{"word":"决议","pinyin":"juéyì","meaning_vi":"nghị quyết, quyết định","hsk30_level":"7-9","specialized":false},{"word":"全网","pinyin":"quánwǎng","meaning_vi":"toàn mạng, toàn thị trường","hsk30_level":null,"specialized":true},{"word":"其中","pinyin":"qízhōng","meaning_vi":"trong đó","hsk30_level":4,"specialized":false},{"word":"多单","pinyin":"duōdān","meaning_vi":"lệnh Long","hsk30_level":null,"specialized":true}],"grammar_notes":["受…影响: cụm trạng ngữ nguyên nhân thường gặp trong tin tức.","五亿: 亿 = 100 triệu, nên 五亿美元 = 500 triệu USD."],"term_notes":[{"term":"全网爆仓","explain":"Tổng giá trị vị thế bị thanh lý trên các sàn, số liệu thường lấy từ các trang như CoinGlass."}],"common_mistakes":[{"wrong":"五亿美元 → 5 tỷ USD","why":"亿 là 100 triệu, không phải tỷ; 五亿 = 500 triệu."}],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"news","set":"crypto-trading-50"},{"id":"w3t-49","topic_id":"web3","subtopic_id":"web3.exchange","exercise_type":"paragraph","direction":"vi-zh","hsk30_level":6,"hsk30_basis":"manual","hsk20_level":null,"title":"Tạm ngừng nạp rút để nâng cấp mạng","context":null,"roles":null,"prompt":"Để phối hợp với việc nâng cấp mạng lưới, nền tảng sẽ tạm ngừng dịch vụ nạp và rút đồng coin này vào thứ Bảy tuần này, giao dịch không bị ảnh hưởng. Sau khi nâng cấp xong, dịch vụ nạp rút sẽ được khôi phục dần, thời gian cụ thể theo thông báo tiếp theo.","answer":"为配合网络升级，平台将于本周六暂停该币种的充值和提币服务，交易不受影响。升级完成后，充提服务将逐步恢复，具体时间以后续公告为准。","pinyin":"Wèi pèihé wǎngluò shēngjí, píngtái jiāng yú běn zhōuliù zàntíng gāi bìzhǒng de chōngzhí hé tíbì fúwù, jiāoyì bú shòu yǐngxiǎng. Shēngjí wánchéng hòu, chōngtí fúwù jiāng zhúbù huīfù, jùtǐ shíjiān yǐ hòuxù gōnggào wéizhǔn.","alternative_answers":[],"segments":[{"who":null,"zh":"为配合网络升级，平台将于本周六暂停该币种的充值和提币服务，交易不受影响。","pinyin":"Wèi pèihé wǎngluò shēngjí, píngtái jiāng yú běn zhōuliù zàntíng gāi bìzhǒng de chōngzhí hé tíbì fúwù, jiāoyì bú shòu yǐngxiǎng.","vi":"Để phối hợp với việc nâng cấp mạng lưới, nền tảng sẽ tạm ngừng dịch vụ nạp và rút đồng coin này vào thứ Bảy tuần này, giao dịch không bị ảnh hưởng.","alt_zh":[{"zh":"为了配合网络升级，平台将在本周六暂停该币种的充提服务，交易不受影响。","pinyin":"Wèile pèihé wǎngluò shēngjí, píngtái jiāng zài běn zhōuliù zàntíng gāi bìzhǒng de chōngtí fúwù, jiāoyì bú shòu yǐngxiǎng.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"升级完成后，充提服务将逐步恢复，具体时间以后续公告为准。","pinyin":"Shēngjí wánchéng hòu, chōngtí fúwù jiāng zhúbù huīfù, jùtǐ shíjiān yǐ hòuxù gōnggào wéizhǔn.","vi":"Sau khi nâng cấp xong, dịch vụ nạp rút sẽ được khôi phục dần, thời gian cụ thể theo thông báo tiếp theo.","alt_zh":[{"zh":"升级完成以后，充提服务会逐步恢复，具体时间请以后续公告为准。","pinyin":"Shēngjí wánchéng yǐhòu, chōngtí fúwù huì zhúbù huīfù, jùtǐ shíjiān qǐng yǐ hòuxù gōnggào wéizhǔn.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"配合","pinyin":"pèihé","meaning_vi":"phối hợp","hsk30_level":5,"specialized":false},{"word":"升级","pinyin":"shēngjí","meaning_vi":"nâng cấp","hsk30_level":5,"specialized":false},{"word":"暂停","pinyin":"zàntíng","meaning_vi":"tạm ngừng","hsk30_level":4,"specialized":false},{"word":"该","pinyin":"gāi","meaning_vi":"… này (văn viết)","hsk30_level":3,"specialized":false},{"word":"逐步","pinyin":"zhúbù","meaning_vi":"dần dần","hsk30_level":5,"specialized":false},{"word":"恢复","pinyin":"huīfù","meaning_vi":"khôi phục","hsk30_level":5,"specialized":false},{"word":"公告","pinyin":"gōnggào","meaning_vi":"thông báo","hsk30_level":6,"specialized":false}],"grammar_notes":["以…为准: \"lấy… làm chuẩn\", cụm cố định trong thông báo.","为 + động từ: \"để…\", văn viết của 为了."],"term_notes":[{"term":"充提","explain":"Viết tắt của 充值 và 提币 (nạp và rút)."},{"term":"网络升级","explain":"Nâng cấp mạng (hard fork, soft fork); sàn thường tạm ngừng nạp rút để tránh lỗi."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"news","set":"crypto-trading-50"}];
window.TR_PACKS["w3t-b79"]=[{"id":"w3t-21","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"vi-zh","hsk30_level":"Ngoài HSK","hsk30_basis":"manual","hsk20_level":null,"title":"Hợp đồng U-margined và coin-margined","context":null,"roles":null,"prompt":"Hợp đồng ký quỹ bằng USDT (U-margined) dùng USDT làm tiền ký quỹ và tiền thanh toán, lãi lỗ tính trực tiếp bằng USDT. Hợp đồng ký quỹ bằng coin (coin-margined) thì dùng tiền mã hóa như BTC làm ký quỹ, phù hợp với người nắm giữ đồng đó lâu dài nhưng muốn phòng hộ rủi ro.","answer":"U本位合约用USDT作为保证金和结算货币，盈亏直接以USDT计算。币本位合约则用BTC等加密货币作为保证金，适合长期持有该币种、又想对冲风险的用户。","pinyin":"U běnwèi héyuē yòng USDT zuòwéi bǎozhèngjīn hé jiésuàn huòbì, yíngkuī zhíjiē yǐ USDT jìsuàn. Bì běnwèi héyuē zé yòng BTC děng jiāmì huòbì zuòwéi bǎozhèngjīn, shìhé chángqī chíyǒu gāi bìzhǒng, yòu xiǎng duìchōng fēngxiǎn de yònghù.","alternative_answers":[],"segments":[{"who":null,"zh":"U本位合约用USDT作为保证金和结算货币，盈亏直接以USDT计算。","pinyin":"U běnwèi héyuē yòng USDT zuòwéi bǎozhèngjīn hé jiésuàn huòbì, yíngkuī zhíjiē yǐ USDT jìsuàn.","vi":"Hợp đồng ký quỹ bằng USDT (U-margined) dùng USDT làm tiền ký quỹ và tiền thanh toán, lãi lỗ tính trực tiếp bằng USDT.","alt_zh":[{"zh":"U本位合约以USDT作为保证金和结算货币，盈亏直接按USDT计算。","pinyin":"U běnwèi héyuē yǐ USDT zuòwéi bǎozhèngjīn hé jiésuàn huòbì, yíngkuī zhíjiē àn USDT jìsuàn.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"币本位合约则用BTC等加密货币作为保证金，适合长期持有该币种、又想对冲风险的用户。","pinyin":"Bì běnwèi héyuē zé yòng BTC děng jiāmì huòbì zuòwéi bǎozhèngjīn, shìhé chángqī chíyǒu gāi bìzhǒng, yòu xiǎng duìchōng fēngxiǎn de yònghù.","vi":"Hợp đồng ký quỹ bằng coin (coin-margined) thì dùng tiền mã hóa như BTC làm ký quỹ, phù hợp với người nắm giữ đồng đó lâu dài nhưng muốn phòng hộ rủi ro.","alt_zh":[{"zh":"币本位合约则以BTC等加密货币作为保证金，适合长期持币又想对冲风险的用户。","pinyin":"Bì běnwèi héyuē zé yǐ BTC děng jiāmì huòbì zuòwéi bǎozhèngjīn, shìhé chángqī chí bì yòu xiǎng duìchōng fēngxiǎn de yònghù.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"U本位","pinyin":"U běnwèi","meaning_vi":"ký quỹ bằng USDT","hsk30_level":null,"specialized":true},{"word":"币本位","pinyin":"bì běnwèi","meaning_vi":"ký quỹ bằng coin","hsk30_level":null,"specialized":true},{"word":"结算","pinyin":"jiésuàn","meaning_vi":"thanh toán, quyết toán","hsk30_level":"7-9","specialized":false},{"word":"盈亏","pinyin":"yíngkuī","meaning_vi":"lãi lỗ","hsk30_level":null,"specialized":true},{"word":"币种","pinyin":"bìzhǒng","meaning_vi":"loại coin","hsk30_level":null,"specialized":true},{"word":"对冲","pinyin":"duìchōng","meaning_vi":"phòng hộ (hedge)","hsk30_level":null,"specialized":true}],"grammar_notes":["用 A 作为 B: \"dùng A làm B\".","则: \"còn, thì\", nối hai vế đối chiếu, văn viết.","又想…: 又 nối thêm một mong muốn song song."],"term_notes":[{"term":"U本位 / 币本位","explain":"U-margined: ký quỹ và lãi lỗ bằng USDT, dễ tính. Coin-margined: ký quỹ bằng chính đồng coin, lãi lỗ tính bằng coin nên giá trị tài khoản biến động theo giá coin."},{"term":"对冲","explain":"Hedge: mở vị thế ngược chiều để giảm rủi ro biến động giá của tài sản đang nắm giữ."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"futures","set":"crypto-trading-50"},{"id":"w3t-27","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"vi-zh","hsk30_level":"Ngoài HSK","hsk30_basis":"manual","hsk20_level":null,"title":"Lệnh Post Only và Reduce Only","context":null,"roles":null,"prompt":"Lệnh \"Post Only\" chỉ được đưa vào sổ lệnh dưới dạng lệnh chờ, nếu lệnh sẽ khớp ngay thì hệ thống tự hủy, nhờ đó đảm bảo được hưởng phí Maker. Lệnh \"Reduce Only\" chỉ có thể giảm vị thế hiện có, không vô tình mở vị thế mới theo hướng ngược lại.","answer":"“只做Maker”订单只会以挂单方式进入订单簿，如果会立即成交，系统就会自动取消，从而保证享受Maker费率。“只减仓”订单只能减少现有仓位，不会意外开出反方向的新仓位。","pinyin":"\"Zhǐ zuò Maker\" dìngdān zhǐ huì yǐ guàdān fāngshì jìnrù dìngdānbù, rúguǒ huì lìjí chéngjiāo, xìtǒng jiù huì zìdòng qǔxiāo, cóng'ér bǎozhèng xiǎngshòu Maker fèilǜ. \"Zhǐ jiǎncāng\" dìngdān zhǐnéng jiǎnshǎo xiànyǒu cāngwèi, búhuì yìwài kāichū fǎn fāngxiàng de xīn cāngwèi.","alternative_answers":[],"segments":[{"who":null,"zh":"“只做Maker”订单只会以挂单方式进入订单簿，如果会立即成交，系统就会自动取消，从而保证享受Maker费率。","pinyin":"\"Zhǐ zuò Maker\" dìngdān zhǐ huì yǐ guàdān fāngshì jìnrù dìngdānbù, rúguǒ huì lìjí chéngjiāo, xìtǒng jiù huì zìdòng qǔxiāo, cóng'ér bǎozhèng xiǎngshòu Maker fèilǜ.","vi":"Lệnh \"Post Only\" chỉ được đưa vào sổ lệnh dưới dạng lệnh chờ, nếu lệnh sẽ khớp ngay thì hệ thống tự hủy, nhờ đó đảm bảo được hưởng phí Maker.","alt_zh":[{"zh":"“只做Maker”的订单只能作为挂单进入订单簿，一旦会马上成交，系统就自动撤单，以确保享受Maker费率。","pinyin":"\"Zhǐ zuò Maker\" de dìngdān zhǐnéng zuòwéi guàdān jìnrù dìngdānbù, yídàn huì mǎshàng chéngjiāo, xìtǒng jiù zìdòng chèdān, yǐ quèbǎo xiǎngshòu Maker fèilǜ.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"“只减仓”订单只能减少现有仓位，不会意外开出反方向的新仓位。","pinyin":"\"Zhǐ jiǎncāng\" dìngdān zhǐnéng jiǎnshǎo xiànyǒu cāngwèi, búhuì yìwài kāichū fǎn fāngxiàng de xīn cāngwèi.","vi":"Lệnh \"Reduce Only\" chỉ có thể giảm vị thế hiện có, không vô tình mở vị thế mới theo hướng ngược lại.","alt_zh":[{"zh":"“只减仓”订单只会减少已有的仓位，不会不小心开出相反方向的新仓位。","pinyin":"\"Zhǐ jiǎncāng\" dìngdān zhǐ huì jiǎnshǎo yǐyǒu de cāngwèi, búhuì bù xiǎoxīn kāichū xiāngfǎn fāngxiàng de xīn cāngwèi.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"订单簿","pinyin":"dìngdānbù","meaning_vi":"sổ lệnh (order book)","hsk30_level":null,"specialized":true},{"word":"立即","pinyin":"lìjí","meaning_vi":"ngay lập tức","hsk30_level":5,"specialized":false},{"word":"取消","pinyin":"qǔxiāo","meaning_vi":"hủy","hsk30_level":4,"specialized":false},{"word":"从而","pinyin":"cóng'ér","meaning_vi":"từ đó, nhờ đó","hsk30_level":5,"specialized":false},{"word":"费率","pinyin":"fèilǜ","meaning_vi":"mức phí","hsk30_level":null,"specialized":true},{"word":"减仓","pinyin":"jiǎncāng","meaning_vi":"giảm vị thế","hsk30_level":null,"specialized":true},{"word":"反方向","pinyin":"fǎn fāngxiàng","meaning_vi":"hướng ngược lại","hsk30_level":null,"specialized":true}],"grammar_notes":["以…方式: \"theo cách…\", văn viết.","从而: \"từ đó, nhờ vậy\", nối kết quả."],"term_notes":[{"term":"只做Maker (Post Only)","explain":"Lệnh chỉ được làm Maker; nếu đặt vào sẽ khớp ngay (thành Taker) thì bị hủy."},{"term":"只减仓 (Reduce Only)","explain":"Lệnh chỉ dùng để đóng bớt vị thế; thường dùng cho lệnh chốt lời, cắt lỗ."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"margin","set":"crypto-trading-50"},{"id":"w3t-33","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"vi-zh","hsk30_level":"Ngoài HSK","hsk30_basis":"manual","hsk20_level":null,"title":"Phân kỳ MACD","context":null,"roles":null,"prompt":"Khi giá lập đỉnh mới nhưng biểu đồ cột MACD không lập đỉnh mới theo thì hình thành phân kỳ giảm (phân kỳ đỉnh), cho thấy động lực tăng đang yếu dần. Tuy nhiên, phân kỳ chỉ là tín hiệu cảnh báo, không thể dùng riêng làm lý do mở Short.","answer":"当价格创出新高，而MACD柱状图却没有跟着创新高，就形成了顶背离，说明上涨动能正在减弱。不过，背离只是提示，不能单独作为开空的理由。","pinyin":"Dāng jiàgé chuàngchū xīngāo, ér MACD zhùzhuàngtú què méiyǒu gēnzhe chuàngxīngāo, jiù xíngchéng le dǐngbèilí, shuōmíng shàngzhǎng dòngnéng zhèngzài jiǎnruò. Búguò, bèilí zhǐshì tíshì, bùnéng dāndú zuòwéi kāi kōng de lǐyóu.","alternative_answers":[],"segments":[{"who":null,"zh":"当价格创出新高，而MACD柱状图却没有跟着创新高，就形成了顶背离，说明上涨动能正在减弱。","pinyin":"Dāng jiàgé chuàngchū xīngāo, ér MACD zhùzhuàngtú què méiyǒu gēnzhe chuàngxīngāo, jiù xíngchéng le dǐngbèilí, shuōmíng shàngzhǎng dòngnéng zhèngzài jiǎnruò.","vi":"Khi giá lập đỉnh mới nhưng biểu đồ cột MACD không lập đỉnh mới theo thì hình thành phân kỳ giảm (phân kỳ đỉnh), cho thấy động lực tăng đang yếu dần.","alt_zh":[{"zh":"价格创新高，但MACD柱状图没有同步创新高，就形成顶背离，说明上涨动能在减弱。","pinyin":"Jiàgé chuàngxīngāo, dàn MACD zhùzhuàngtú méiyǒu tóngbù chuàngxīngāo, jiù xíngchéng dǐngbèilí, shuōmíng shàngzhǎng dòngnéng zài jiǎnruò.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"不过，背离只是提示，不能单独作为开空的理由。","pinyin":"Búguò, bèilí zhǐshì tíshì, bùnéng dāndú zuòwéi kāi kōng de lǐyóu.","vi":"Tuy nhiên, phân kỳ chỉ là tín hiệu cảnh báo, không thể dùng riêng làm lý do mở Short.","alt_zh":[{"zh":"不过背离只是一种提示，不能单独当作做空的理由。","pinyin":"Búguò bèilí zhǐshì yìzhǒng tíshì, bùnéng dāndú dàngzuò zuòkōng de lǐyóu.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"创新高","pinyin":"chuàngxīngāo","meaning_vi":"lập đỉnh mới","hsk30_level":null,"specialized":true},{"word":"柱状图","pinyin":"zhùzhuàngtú","meaning_vi":"biểu đồ cột","hsk30_level":null,"specialized":true},{"word":"形成","pinyin":"xíngchéng","meaning_vi":"hình thành","hsk30_level":5,"specialized":false},{"word":"顶背离","pinyin":"dǐngbèilí","meaning_vi":"phân kỳ đỉnh","hsk30_level":null,"specialized":true},{"word":"动能","pinyin":"dòngnéng","meaning_vi":"động lực, động năng","hsk30_level":null,"specialized":true},{"word":"减弱","pinyin":"jiǎnruò","meaning_vi":"yếu đi","hsk30_level":6,"specialized":false},{"word":"单独","pinyin":"dāndú","meaning_vi":"riêng lẻ","hsk30_level":5,"specialized":false}],"grammar_notes":["而…却…: \"còn… thì lại…\", nhấn mạnh sự trái ngược.","作为…的理由: \"làm lý do để…\"."],"term_notes":[{"term":"背离","explain":"Divergence: giá và chỉ báo đi ngược nhau. 顶背离 (phân kỳ đỉnh) cảnh báo đà tăng yếu; 底背离 (phân kỳ đáy) cảnh báo đà giảm yếu."},{"term":"MACD","explain":"Chỉ báo hội tụ phân kỳ trung bình động, gồm đường DIF, DEA và biểu đồ cột."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"ta","set":"crypto-trading-50"},{"id":"w3t-37","topic_id":"web3","subtopic_id":"web3.trading","exercise_type":"paragraph","direction":"vi-zh","hsk30_level":"Ngoài HSK","hsk30_basis":"manual","hsk20_level":null,"title":"Arbitrage funding rate","context":null,"roles":null,"prompt":"Cách làm phổ biến của arbitrage funding rate là: mua spot, đồng thời mở lệnh Short với khối lượng tương đương trên hợp đồng vĩnh cửu. Như vậy biến động giá về cơ bản được phòng hộ, người dùng chủ yếu kiếm phí funding dương. Nhưng vẫn phải chú ý rủi ro sàn và thiếu ký quỹ khi thị trường biến động cực đoan.","answer":"资金费率套利的常见做法是：买入现货，同时在永续合约上开出相同数量的空单。这样价格涨跌基本对冲，用户主要赚取正的资金费率。但仍要注意交易所风险和极端行情下的保证金不足。","pinyin":"Zījīn fèilǜ tàolì de chángjiàn zuòfǎ shì: mǎirù xiànhuò, tóngshí zài yǒngxù héyuē shàng kāichū xiāngtóng shùliàng de kōngdān. Zhèyàng jiàgé zhǎngdiē jīběn duìchōng, yònghù zhǔyào zhuànqǔ zhèng de zījīn fèilǜ. Dàn réng yào zhùyì jiāoyìsuǒ fēngxiǎn hé jíduān hángqíng xià de bǎozhèngjīn bùzú.","alternative_answers":[],"segments":[{"who":null,"zh":"资金费率套利的常见做法是：买入现货，同时在永续合约上开出相同数量的空单。","pinyin":"Zījīn fèilǜ tàolì de chángjiàn zuòfǎ shì: mǎirù xiànhuò, tóngshí zài yǒngxù héyuē shàng kāichū xiāngtóng shùliàng de kōngdān.","vi":"Cách làm phổ biến của arbitrage funding rate là: mua spot, đồng thời mở lệnh Short với khối lượng tương đương trên hợp đồng vĩnh cửu.","alt_zh":[{"zh":"资金费率套利常见的做法是买入现货，同时在永续合约开等量的空单。","pinyin":"Zījīn fèilǜ tàolì chángjiàn de zuòfǎ shì mǎirù xiànhuò, tóngshí zài yǒngxù héyuē kāi děng liàng de kōngdān.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"这样价格涨跌基本对冲，用户主要赚取正的资金费率。","pinyin":"Zhèyàng jiàgé zhǎngdiē jīběn duìchōng, yònghù zhǔyào zhuànqǔ zhèng de zījīn fèilǜ.","vi":"Như vậy biến động giá về cơ bản được phòng hộ, người dùng chủ yếu kiếm phí funding dương.","alt_zh":[{"zh":"这样涨跌基本上互相抵消，主要赚的是正资金费率。","pinyin":"Zhèyàng zhǎngdiē jīběnshang hùxiāng dǐxiāo, zhǔyào zhuàn de shì zhèng zījīn fèilǜ.","note":"Cách dịch tương đương"}],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"但仍要注意交易所风险和极端行情下的保证金不足。","pinyin":"Dàn réng yào zhùyì jiāoyìsuǒ fēngxiǎn hé jíduān hángqíng xià de bǎozhèngjīn bùzú.","vi":"Nhưng vẫn phải chú ý rủi ro sàn và thiếu ký quỹ khi thị trường biến động cực đoan.","alt_zh":[],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"套利","pinyin":"tàolì","meaning_vi":"kinh doanh chênh lệch (arbitrage)","hsk30_level":null,"specialized":true},{"word":"做法","pinyin":"zuòfǎ","meaning_vi":"cách làm","hsk30_level":4,"specialized":false},{"word":"相同","pinyin":"xiāngtóng","meaning_vi":"giống nhau","hsk30_level":4,"specialized":false},{"word":"数量","pinyin":"shùliàng","meaning_vi":"số lượng","hsk30_level":4,"specialized":false},{"word":"基本","pinyin":"jīběn","meaning_vi":"về cơ bản","hsk30_level":4,"specialized":false},{"word":"极端","pinyin":"jíduān","meaning_vi":"cực đoan","hsk30_level":6,"specialized":false}],"grammar_notes":["…的做法是：…: dấu hai chấm giới thiệu nội dung.","仍要: \"vẫn phải\", văn viết của 还是要."],"term_notes":[{"term":"期现套利 / 资金费率套利","explain":"Mua spot và Short perpetual cùng khối lượng (delta trung tính) để thu funding dương; rủi ro chính là sàn sập, funding đổi chiều và bị thanh lý chân Short khi giá tăng vọt."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"strategy","set":"crypto-trading-50"},{"id":"w3t-44","topic_id":"web3","subtopic_id":"web3.wallet","exercise_type":"paragraph","direction":"zh-vi","hsk30_level":"Ngoài HSK","hsk30_basis":"manual","hsk20_level":null,"title":"Thu hồi quyền cấp cho hợp đồng","context":null,"roles":null,"prompt":"在DeFi里使用代币之前，往往需要先给智能合约授权。如果授权了来路不明的合约，资产可能被盗走。定期检查并撤销不再使用的授权，是保护钱包安全的好习惯。","answer":"Trước khi dùng token trong DeFi, thường phải cấp quyền cho hợp đồng thông minh trước. Nếu cấp quyền cho hợp đồng không rõ nguồn gốc, tài sản có thể bị đánh cắp. Thường xuyên kiểm tra và thu hồi những quyền không còn dùng là thói quen tốt để bảo vệ an toàn cho ví.","pinyin":"Zài DeFi lǐ shǐyòng dàibì zhīqián, wǎngwǎng xūyào xiān gěi zhìnéng héyuē shòuquán. Rúguǒ shòuquán le láilùbùmíng de héyuē, zīchǎn kěnéng bèi dàozǒu. Dìngqī jiǎnchá bìng chèxiāo búzài shǐyòng de shòuquán, shì bǎohù qiánbāo ānquán de hǎo xíguàn.","alternative_answers":[],"segments":[{"who":null,"zh":"在DeFi里使用代币之前，往往需要先给智能合约授权。","pinyin":"Zài DeFi lǐ shǐyòng dàibì zhīqián, wǎngwǎng xūyào xiān gěi zhìnéng héyuē shòuquán.","vi":"Trước khi dùng token trong DeFi, thường phải cấp quyền cho hợp đồng thông minh trước.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"如果授权了来路不明的合约，资产可能被盗走。","pinyin":"Rúguǒ shòuquán le láilùbùmíng de héyuē, zīchǎn kěnéng bèi dàozǒu.","vi":"Nếu cấp quyền cho hợp đồng không rõ nguồn gốc, tài sản có thể bị đánh cắp.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"定期检查并撤销不再使用的授权，是保护钱包安全的好习惯。","pinyin":"Dìngqī jiǎnchá bìng chèxiāo búzài shǐyòng de shòuquán, shì bǎohù qiánbāo ānquán de hǎo xíguàn.","vi":"Thường xuyên kiểm tra và thu hồi những quyền không còn dùng là thói quen tốt để bảo vệ an toàn cho ví.","alt_zh":[],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"往往","pinyin":"wǎngwǎng","meaning_vi":"thường thường","hsk30_level":4,"specialized":false},{"word":"授权","pinyin":"shòuquán","meaning_vi":"cấp quyền","hsk30_level":"7-9","specialized":false},{"word":"来路不明","pinyin":"láilùbùmíng","meaning_vi":"không rõ nguồn gốc","hsk30_level":null,"specialized":true},{"word":"盗走","pinyin":"dàozǒu","meaning_vi":"đánh cắp","hsk30_level":null,"specialized":true},{"word":"撤销","pinyin":"chèxiāo","meaning_vi":"thu hồi, hủy bỏ","hsk30_level":6,"specialized":false},{"word":"习惯","pinyin":"xíguàn","meaning_vi":"thói quen","hsk30_level":3,"specialized":false}],"grammar_notes":["给 + đối tượng + động từ: \"cho…\" (给智能合约授权).","动词 + 并 + 动词: 并 nối hai hành động, văn viết."],"term_notes":[{"term":"授权 (Approve)","explain":"Cho phép một hợp đồng thông minh tiêu một lượng token của bạn; quyền cấp không giới hạn rất nguy hiểm nếu hợp đồng bị hack hoặc là lừa đảo."},{"term":"撤销授权 (Revoke)","explain":"Thu hồi quyền đã cấp, làm qua các công cụ kiểm tra quyền token."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Đối chiếu nội dung với hướng dẫn \"Cách thu hồi quyền truy cập hợp đồng thông minh vào tiền mã hóa của bạn\" trên ethereum.org (bản tiếng Trung, MIT). Câu văn tự biên soạn, không chép nguyên văn. Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"defi","set":"crypto-trading-50"},{"id":"w3t-50","topic_id":"web3","subtopic_id":"web3.exchange","exercise_type":"paragraph","direction":"zh-vi","hsk30_level":"Ngoài HSK","hsk30_basis":"manual","hsk20_level":null,"title":"Bằng chứng dự trữ","context":null,"roles":null,"prompt":"为了提高透明度，越来越多交易所定期公布储备金证明，用默克尔树让用户自行验证自己的资产是否被计入。不过，储备金证明只能说明资产情况，并不能完全反映交易所的负债。","answer":"Để tăng tính minh bạch, ngày càng nhiều sàn định kỳ công bố bằng chứng dự trữ, dùng cây Merkle để người dùng tự kiểm tra tài sản của mình có được tính vào hay không. Tuy nhiên, bằng chứng dự trữ chỉ thể hiện tình hình tài sản, không thể phản ánh đầy đủ các khoản nợ của sàn.","pinyin":"Wèile tígāo tòumíngdù, yuèláiyuè duō jiāoyìsuǒ dìngqī gōngbù chǔbèijīn zhèngmíng, yòng mòkè'ěrshù ràng yònghù zìxíng yànzhèng zìjǐ de zīchǎn shìfǒu bèi jìrù. Búguò, chǔbèijīn zhèngmíng zhǐnéng shuōmíng zīchǎn qíngkuàng, bìng bùnéng wánquán fǎnyìng jiāoyìsuǒ de fùzhài.","alternative_answers":[],"segments":[{"who":null,"zh":"为了提高透明度，越来越多交易所定期公布储备金证明，用默克尔树让用户自行验证自己的资产是否被计入。","pinyin":"Wèile tígāo tòumíngdù, yuèláiyuè duō jiāoyìsuǒ dìngqī gōngbù chǔbèijīn zhèngmíng, yòng mòkè'ěrshù ràng yònghù zìxíng yànzhèng zìjǐ de zīchǎn shìfǒu bèi jìrù.","vi":"Để tăng tính minh bạch, ngày càng nhiều sàn định kỳ công bố bằng chứng dự trữ, dùng cây Merkle để người dùng tự kiểm tra tài sản của mình có được tính vào hay không.","alt_zh":[],"alt_vi":[],"avoid_zh":[]},{"who":null,"zh":"不过，储备金证明只能说明资产情况，并不能完全反映交易所的负债。","pinyin":"Búguò, chǔbèijīn zhèngmíng zhǐnéng shuōmíng zīchǎn qíngkuàng, bìng bùnéng wánquán fǎnyìng jiāoyìsuǒ de fùzhài.","vi":"Tuy nhiên, bằng chứng dự trữ chỉ thể hiện tình hình tài sản, không thể phản ánh đầy đủ các khoản nợ của sàn.","alt_zh":[],"alt_vi":[],"avoid_zh":[]}],"vocabulary":[{"word":"透明度","pinyin":"tòumíngdù","meaning_vi":"độ minh bạch","hsk30_level":null,"specialized":true},{"word":"公布","pinyin":"gōngbù","meaning_vi":"công bố","hsk30_level":5,"specialized":false},{"word":"储备金证明","pinyin":"chǔbèijīn zhèngmíng","meaning_vi":"bằng chứng dự trữ","hsk30_level":null,"specialized":true},{"word":"默克尔树","pinyin":"mòkè'ěrshù","meaning_vi":"cây Merkle","hsk30_level":null,"specialized":true},{"word":"自行","pinyin":"zìxíng","meaning_vi":"tự mình","hsk30_level":"7-9","specialized":false},{"word":"验证","pinyin":"yànzhèng","meaning_vi":"xác minh","hsk30_level":6,"specialized":false},{"word":"负债","pinyin":"fùzhài","meaning_vi":"khoản nợ","hsk30_level":null,"specialized":true}],"grammar_notes":["越来越多 + danh từ: \"ngày càng nhiều…\".","并不能: 并 nhấn mạnh phủ định \"hoàn toàn không thể\"."],"term_notes":[{"term":"储备金证明 (Proof of Reserves)","explain":"Sàn chứng minh đang giữ đủ tài sản của khách hàng; xuất hiện nhiều sau sự sụp đổ của FTX năm 2022."},{"term":"默克尔树","explain":"Merkle tree: cấu trúc dữ liệu cho phép mỗi người tự kiểm tra số dư của mình có trong tổng mà không lộ dữ liệu người khác."}],"common_mistakes":[],"source":"original","created_by":"ai","reviewed":false,"quality_status":"auto_checked","source_note":"Tự biên soạn (AI – Claude), chưa được người duyệt. Thuật ngữ theo cách dùng phổ biến trên các sàn và trang học crypto tiếng Trung (Binance Academy, OKX Learn, ethereum.org…), chỉ tham khảo thuật ngữ, không chép nội dung.","content_area":"news","set":"crypto-trading-50"}];
